INSERT INTO gw1_skilldesc (id, pve_name, pve_desc, pve_concise, pvp_name, pvp_desc, pvp_concise) VALUES
  (0, 'No Skill', 'Empty skill slot', 'Empty slot', 'No Skill', 'Empty skill slot', 'Empty slot'),
  (1, 'Healing Signet', 'Signet. You gain 82...172 Health. You have -40 armor while using this skill.', 'Signet. You gain 82...172 Health. You have -40 armor while using this skill.', 'Healing Signet', 'Signet. You gain 82...172 Health. You have -40 armor while using this skill.', 'Signet. You gain 82...172 Health. You have -40 armor while using this skill.'),
  (2, 'Resurrection Signet', 'Signet. Resurrect target party member. That party member is returned to life with 100% Health and 25% Energy. This signet only recharges when you gain a morale boost.', 'Signet. Resurrects target party member (100% Health, 25% Energy). This signet only recharges when you gain a morale boost.', 'Resurrection Signet', 'Signet. Resurrect target party member. That party member is returned to life with 100% Health and 25% Energy. This signet only recharges when you gain a morale boost.', 'Signet. Resurrects target party member (100% Health, 25% Energy). This signet only recharges when you gain a morale boost.'),
  (3, 'Signet of Capture', 'Signet. Choose one skill from a nearby dead Boss of your profession. Signet of Capture is permanently replaced by that skill. If that skill was elite, gain 250 XP for every level you have earned.', 'Signet. Choose one skill from a nearby dead Boss of your profession. Signet of Capture is permanently replaced by that skill. If that skill was elite, gain 250 XP for every level you have earned.', 'Signet of Capture', 'Signet. Choose one skill from a nearby dead Boss of your profession. Signet of Capture is permanently replaced by that skill. If that skill was elite, gain 250 XP for every level you have earned.', 'Signet. Choose one skill from a nearby dead Boss of your profession. Signet of Capture is permanently replaced by that skill. If that skill was elite, gain 250 XP for every level you have earned.'),
  (5, 'Power Block', 'Elite Spell. If target foe is casting a spell or chant, that skill and all skills of the same attribute are disabled for 1...12 seconds and that skill is interrupted.', 'Elite Spell. If target foe is casting a spell or chant, that skill and all skills of the same attribute are disabled (1...12 seconds) and that skill is interrupted.', 'Power Block', 'Elite Spell. If target foe is casting a spell or chant, that skill and all skills of the same attribute are disabled for 1...12 seconds and that skill is interrupted.', 'Elite Spell. If target foe is casting a spell or chant, that skill and all skills of the same attribute are disabled (1...12 seconds) and that skill is interrupted.'),
  (6, 'Mantra of Earth', 'Stance. For 30...90 seconds, whenever you take earth damage, the damage is reduced by 26...50% and you gain 2 Energy.', 'Stance. (30...90 seconds.) Reduces earth damage you take by 26...50%. You gain 2 Energy when you take earth damage.', 'Mantra of Earth', 'Stance. For 30...90 seconds, whenever you take earth damage, the damage is reduced by 26...50% and you gain 2 Energy.', 'Stance. (30...90 seconds.) Reduces earth damage you take by 26...50%. You gain 2 Energy when you take earth damage.'),
  (7, 'Mantra of Flame', 'Stance. For 30...90 seconds, whenever you take fire damage, the damage is reduced by 26...50% and you gain 2 Energy.', 'Stance. (30...90 seconds.) Reduces fire damage you take by 26...50%. You gain 2 Energy when you take fire damage.', 'Mantra of Flame', 'Stance. For 30...90 seconds, whenever you take fire damage, the damage is reduced by 26...50% and you gain 2 Energy.', 'Stance. (30...90 seconds.) Reduces fire damage you take by 26...50%. You gain 2 Energy when you take fire damage.'),
  (8, 'Mantra of Frost', 'Stance. For 30...90 seconds, whenever you take cold damage, the damage is reduced by 26...50% and you gain 2 Energy.', 'Stance. (30...90 seconds.) Reduces cold damage you take by 26...50%. You gain 2 Energy when you take cold damage.', 'Mantra of Frost', 'Stance. For 30...90 seconds, whenever you take cold damage, the damage is reduced by 26...50% and you gain 2 Energy.', 'Stance. (30...90 seconds.) Reduces cold damage you take by 26...50%. You gain 2 Energy when you take cold damage.'),
  (9, 'Mantra of Lightning', 'Stance. For 30...90 seconds, whenever you take lightning damage, the damage is reduced by 26...50% and you gain 2 Energy.', 'Stance. (30...90 seconds.) Reduces lightning damage you take by 26...50%. You gain 2 Energy when you take lightning damage.', 'Mantra of Lightning', 'Stance. For 30...90 seconds, whenever you take lightning damage, the damage is reduced by 26...50% and you gain 2 Energy.', 'Stance. (30...90 seconds.) Reduces lightning damage you take by 26...50%. You gain 2 Energy when you take lightning damage.'),
  (10, 'Hex Breaker', 'Stance. For 5...80 seconds, the next time you are the target of a hex, that hex fails and the caster takes 10...46 damage.', 'Stance. (5...80 seconds.) The next hex against you fails and the caster takes 10...46 damage.', 'Hex Breaker', 'Stance. For 5...80 seconds, the next time you are the target of a hex, that hex fails and the caster takes 10...46 damage.', 'Stance. (5...80 seconds.) The next hex against you fails and the caster takes 10...46 damage.'),
  (11, 'Distortion', 'Stance. For 1...5 seconds, you have a 75% chance to block attacks. Whenever you block an attack this way, you lose 2 Energy or Distortion ends.', 'Stance. (1...5 seconds.) You have 75% chance to block. Block cost: you lose 2 Energy or Distortion ends.', 'Distortion', 'Stance. For 1...5 seconds, you have a 75% chance to block attacks. Whenever you block an attack this way, you lose 2 Energy or Distortion ends.', 'Stance. (1...5 seconds.) You have 75% chance to block. Block cost: you lose 2 Energy or Distortion ends.'),
  (13, 'Mantra of Recovery', 'Elite Stance. For 5...20 seconds, spells you cast recharge 33% faster.', 'Elite Stance. (5...20 seconds.) Your spells recharge 33% faster.', 'Mantra of Recovery', 'Elite Stance. For 5...20 seconds, spells you cast recharge 33% faster.', 'Elite Stance. (5...20 seconds.) Your spells recharge 33% faster.'),
  (14, 'Mantra of Persistence', 'Stance. For 5...25 seconds, any Illusion Magic hex you cast lasts 10...40% longer.', 'Stance. (5...25 seconds.) Illusion hexes you cast last 10...40% longer.', 'Mantra of Persistence', 'Stance. For 5...25 seconds, any Illusion Magic hex you cast lasts 10...40% longer.', 'Stance. (5...25 seconds.) Illusion hexes you cast last 10...40% longer.'),
  (15, 'Mantra of Inscriptions', 'Stance. For 5...25 seconds, signets you successfully activate while in this stance recharge 10...40% faster.', 'Stance. (5...25 seconds.) Signets you successfully activate while in this stance recharge 10...40% faster.', 'Mantra of Inscriptions', 'Stance. For 5...25 seconds, signets you successfully activate while in this stance recharge 10...40% faster.', 'Stance. (5...25 seconds.) Signets you successfully activate while in this stance recharge 10...40% faster.'),
  (16, 'Mantra of Concentration', 'Stance. For 1...38 seconds, the next time you would be interrupted, you are not interrupted.', 'Stance. (1...38 seconds.) The next time you would be interrupted, you are not interrupted.', 'Mantra of Concentration', 'Stance. For 1...38 seconds, the next time you would be interrupted, you are not interrupted.', 'Stance. (1...38 seconds.) The next time you would be interrupted, you are not interrupted.'),
  (17, 'Mantra of Resolve', 'Stance. For 30...90 seconds, you cannot be interrupted, but each time you would have been interrupted, you lose 10...4 Energy or Mantra of Resolve ends.', 'Stance. (30...90 seconds.) Prevents interrupts against you. Prevention cost: lose 10...4 Energy or Mantra of Resolve ends.', 'Mantra of Resolve (PvP)', 'Stance. For 5 seconds, you cannot be interrupted, but each time you would have been interrupted, you lose 10...4 Energy or Mantra of Resolve ends.', 'Stance. (5 seconds.) Prevents interrupts against you. Prevention cost: lose 10...4 Energy or Mantra of Resolve ends.'),
  (18, 'Mantra of Signets', 'Stance. For 10...40 seconds, you have +3 armor for each signet you have equipped. Whenever you use a signet, you gain 5...60 Health.', 'Stance. (10...40 seconds.) You have +3 armor for each signet. You gain 5...60 Health each time you use a signet.', 'Mantra of Signets (PvP)', 'Stance. For 10...40 seconds, you have +3 armor for each signet you have equipped. Whenever you use a signet, you gain 5...60 Health.', 'Stance. (10...40 seconds.) You have +3 armor for each signet. You gain 5...60 Health each time you use a signet.'),
  (19, 'Fragility', 'Hex Spell. For 8...20 seconds, target and adjacent foes take 5...20 damage each time they suffer or recover from a new condition.', 'Hex Spell. Also hexes foes adjacent to target (8...20 seconds). These foes take 5...20 damage each time they gain or lose a condition.', 'Fragility (PvP)', 'Hex Spell. For 8...20 seconds, target and adjacent foes take 5...20 damage each time they suffer or recover from a new condition.', 'Hex Spell. Also hexes foes adjacent to target (8...20 seconds). These foes take 5...20 damage each time they gain or lose a condition.'),
  (21, 'Inspired Enchantment', 'Spell. Remove an enchantment from target foe and gain 3...15 Energy. For 20 seconds, Inspired Enchantment is replaced with the enchantment removed from target foe.', 'Spell. Removes an enchantment from target foe. Removal effects: you gain 3...15 Energy; this spell is replaced with that enchantment (20 seconds).', 'Inspired Enchantment', 'Spell. Remove an enchantment from target foe and gain 3...15 Energy. For 20 seconds, Inspired Enchantment is replaced with the enchantment removed from target foe.', 'Spell. Removes an enchantment from target foe. Removal effects: you gain 3...15 Energy; this spell is replaced with that enchantment (20 seconds).'),
  (22, 'Inspired Hex', 'Spell. Remove a hex from target ally and gain 4...10 Energy. For 20 seconds, Inspired Hex is replaced with the hex that was removed.', 'Spell. Removes a hex from target ally. Removal effects: you gain 4...10 Energy; this spell is replaced with that hex (20 seconds).', 'Inspired Hex', 'Spell. Remove a hex from target ally and gain 4...10 Energy. For 20 seconds, Inspired Hex is replaced with the hex that was removed.', 'Spell. Removes a hex from target ally. Removal effects: you gain 4...10 Energy; this spell is replaced with that hex (20 seconds).'),
  (23, 'Power Spike', 'Spell. If target foe is casting a spell or a chant, that skill is interrupted and target foe takes 30...120 damage.', 'Spell. Interrupts a spell or chant. Interruption effect: deals 30...120 damage.', 'Power Spike', 'Spell. If target foe is casting a spell or a chant, that skill is interrupted and target foe takes 30...120 damage.', 'Spell. Interrupts a spell or chant. Interruption effect: deals 30...120 damage.'),
  (24, 'Power Leak', 'Spell. If target foe is casting a spell or chant, that skill is interrupted and target foe loses 3...17 Energy.', 'Spell. Interrupts a spell or chant. Interruption effect: causes 3...17 Energy loss.', 'Power Leak', 'Spell. If target foe is casting a spell or chant, that skill is interrupted and target foe loses 3...17 Energy.', 'Spell. Interrupts a spell or chant. Interruption effect: causes 3...17 Energy loss.'),
  (25, 'Power Drain', 'Spell. If target foe is casting a spell or chant, that skill is interrupted and you gain 1...31 Energy.', 'Spell. Interrupts a spell or chant. Interruption effect: you gain 1...31 Energy.', 'Power Drain', 'Spell. If target foe is casting a spell or chant, that skill is interrupted and you gain 1...31 Energy.', 'Spell. Interrupts a spell or chant. Interruption effect: you gain 1...31 Energy.'),
  (26, 'Empathy', 'Hex Spell. For 5...15 seconds, whenever target foe attacks, that foe takes 10...55 damage and deals 1...15 less damage.', 'Hex Spell. (5...15 seconds.) Target foe''s attacks deal 1...15 less damage, and that foe takes 10...55 damage with each attack.', 'Empathy (PvP)', 'Hex Spell. For 5...15 seconds, whenever target foe attacks, that foe takes 15...45 damage.', 'Hex Spell. (5...15 seconds.) Target foe takes 15...45 damage whenever it attacks.'),
  (27, 'Shatter Delusions', 'Spell. Remove one Mesmer hex from target foe. If a hex is removed, that foe takes 15...75 damage and all adjacent foes take 75% of that damage.', 'Spell. Removes a Mesmer hex from target foe. Removal effect: 15...75 damage to target and 75% of that damage to all adjacent foes.', 'Shatter Delusions (PvP)', 'Spell. Remove one Mesmer hex from target foe. If a hex is removed, that foe takes 15...75 damage and all adjacent foes take 75% of that damage.', 'Spell. Removes a Mesmer hex from target foe. Removal effect: 15...75 damage to target and 75% of that damage to all adjacent foes.'),
  (28, 'Backfire', 'Hex Spell. For 10 seconds, whenever target foe casts a spell, that foe takes 35...140 damage.', 'Hex Spell. (10 seconds.) Target foe takes 35...140 damage whenever it casts a spell.', 'Backfire', 'Hex Spell. For 10 seconds, whenever target foe casts a spell, that foe takes 35...140 damage.', 'Hex Spell. (10 seconds.) Target foe takes 35...140 damage whenever it casts a spell.'),
  (29, 'Blackout', 'Skill. For 2...8 seconds, all of touched target foe''s skills are disabled, and all of your skills are disabled for 5 seconds.', 'Touch Skill. (2...8 seconds.) Disables skills. Your skills are disabled (5 seconds).', 'Blackout', 'Skill. For 2...8 seconds, all of touched target foe''s skills are disabled, and all of your skills are disabled for 5 seconds.', 'Touch Skill. (2...8 seconds.) Disables skills. Your skills are disabled (5 seconds).'),
  (30, 'Diversion', 'Hex Spell. For 6 seconds, the next time target foe uses a skill, that skill takes an additional 10...56 seconds to recharge.', 'Hex Spell. (6 seconds.) Target foe''s next skill takes +10...56 seconds to recharge.', 'Diversion', 'Hex Spell. For 6 seconds, the next time target foe uses a skill, that skill takes an additional 10...56 seconds to recharge.', 'Hex Spell. (6 seconds.) Target foe''s next skill takes +10...56 seconds to recharge.'),
  (31, 'Conjure Phantasm', 'Hex Spell. For 4...18 seconds, target foe experiences -5 Health degeneration.', 'Hex Spell. (4...18 seconds.) Causes -5 Health degeneration.', 'Conjure Phantasm', 'Hex Spell. For 4...18 seconds, target foe experiences -5 Health degeneration.', 'Hex Spell. (4...18 seconds.) Causes -5 Health degeneration.'),
  (32, 'Illusion of Weakness', 'Enchantment Spell. You lose 50...240 Health. Illusion of Weakness ends if damage drops your Health below 25% of your maximum. When Illusion of Weakness ends, you gain 50...240 Health.', 'Enchantment Spell. Lose 50...240 Health. End effect: you gain 50...240 Health. Ends if damage drops your Health below 25% of your maximum.', 'Illusion of Weakness', 'Enchantment Spell. You lose 50...240 Health. Illusion of Weakness ends if damage drops your Health below 25% of your maximum. When Illusion of Weakness ends, you gain 50...240 Health.', 'Enchantment Spell. Lose 50...240 Health. End effect: you gain 50...240 Health. Ends if damage drops your Health below 25% of your maximum.'),
  (33, 'Illusionary Weaponry', 'Elite Enchantment Spell. For 30 seconds, your melee attacks neither hit nor fail to hit. Instead, Illusionary Weaponry deals 20...60 damage to your targets for each melee attack. You have +5 armor for each equipped Illusion Magic skill.', 'Elite Enchantment Spell. (30 seconds.) Deals 20...60 damage to foes in place of other damage or effects from melee attacks. You have +5 armor for each equipped Illusion Magic skill. Your melee attacks neither hit nor fail to hit.', 'Illusionary Weaponry (PvP)', 'Elite Enchantment Spell. For 30 seconds, your melee attacks neither hit nor fail to hit. Instead, Illusionary Weaponry deals 20...60 damage to your targets for each melee attack.', 'Elite Enchantment Spell. (30 seconds.) Deals 20...60 damage to foes in place of other damage or effects from melee attacks. Your melee attacks neither hit nor fail to hit.'),
  (34, 'Sympathetic Visage', 'Enchantment Spell. For 4...10 seconds, whenever target ally is hit by a melee attack, all adjacent foes lose all adrenaline and 3 Energy.', 'Enchantment Spell. (4...10 seconds.) All adjacent foes lose all adrenaline and 3 Energy whenever a melee attack hits target ally.', 'Sympathetic Visage', 'Enchantment Spell. For 4...10 seconds, whenever target ally is hit by a melee attack, all adjacent foes lose all adrenaline and 3 Energy.', 'Enchantment Spell. (4...10 seconds.) All adjacent foes lose all adrenaline and 3 Energy whenever a melee attack hits target ally.'),
  (35, 'Ignorance', 'Hex Spell. For 8...20 seconds target foe cannot use signets.', 'Hex Spell. (8...20 seconds.) Target foe cannot use signets.', 'Ignorance', 'Hex Spell. For 8...20 seconds target foe cannot use signets.', 'Hex Spell. (8...20 seconds.) Target foe cannot use signets.'),
  (36, 'Arcane Conundrum', 'Hex Spell. For 5...15 seconds, spells cast by target foe and all adjacent foes take twice as long to cast. When this hex ends, you gain 1...7 energy.', 'Hex Spell. Also hexes foes adjacent to target (5...15 seconds). Doubles spell casting time. End effect: you gain 1...7 energy.', 'Arcane Conundrum', 'Hex Spell. For 5...15 seconds, spells cast by target foe and all adjacent foes take twice as long to cast. When this hex ends, you gain 1...7 energy.', 'Hex Spell. Also hexes foes adjacent to target (5...15 seconds). Doubles spell casting time. End effect: you gain 1...7 energy.'),
  (37, 'Illusion of Haste', 'Enchantment Spell. For 5...11 seconds you are no longer Crippled, and you move 33% faster. When Illusion of Haste ends, you become Crippled for 3 seconds.', 'Enchantment Spell. (5...11 seconds.) You move 33% faster. Initial effect: removes Crippled condition. End effect: you are Crippled (3 seconds).', 'Illusion of Haste (PvP)', 'Enchantment Spell. For 5...11 seconds, you move 33% faster. When Illusion of Haste ends, you become Crippled for 3 seconds.', 'Enchantment Spell. (5...11 seconds.) You move 33% faster. End effect: you are Crippled (3 seconds).'),
  (38, 'Channeling', 'Enchantment Spell. For 8...56 seconds, whenever you cast a spell, you gain 1 Energy for each foe in the area.', 'Enchantment Spell. (8...56 seconds.) You gain 1 Energy for each foe in the area whenever you cast a spell.', 'Channeling', 'Enchantment Spell. For 8...56 seconds, whenever you cast a spell, you gain 1 Energy for each foe in the area.', 'Enchantment Spell. (8...56 seconds.) You gain 1 Energy for each foe in the area whenever you cast a spell.'),
  (39, 'Energy Surge', 'Elite Spell. Target foe loses 1...10 Energy. For each point of Energy lost, that foe takes 7 damage and all nearby foes take 75% of that damage.', 'Elite Spell. Causes 1...10 Energy loss. Deals 7 damage to target for each point of Energy lost and 75% of that damage to nearby foes.', 'Energy Surge', 'Elite Spell. Target foe loses 1...10 Energy. For each point of Energy lost, that foe takes 7 damage and all nearby foes take 75% of that damage.', 'Elite Spell. Causes 1...10 Energy loss. Deals 7 damage to target for each point of Energy lost and 75% of that damage to nearby foes.'),
  (40, 'Ether Feast', 'Spell. Target foe loses 3 Energy. You are healed 20...65 for each point of Energy lost.', 'Spell. Causes 3 Energy loss. You gain 20...65 Health for each point of Energy lost.', 'Ether Feast', 'Spell. Target foe loses 3 Energy. You are healed 20...65 for each point of Energy lost.', 'Spell. Causes 3 Energy loss. You gain 20...65 Health for each point of Energy lost.'),
  (41, 'Ether Lord', 'Hex Spell. You lose all Energy. For 5...10 seconds, target foe suffers -1...3 Energy degeneration, and you experience +1...3 Energy regeneration.', 'Hex Spell. You lose all Energy. Target foe has -1...3 Energy degeneration and you have +1...3 Energy regeneration (5...10 seconds).', 'Ether Lord', 'Hex Spell. You lose all Energy. For 5...10 seconds, target foe suffers -1...3 Energy degeneration, and you experience +1...3 Energy regeneration.', 'Hex Spell. You lose all Energy. Target foe has -1...3 Energy degeneration and you have +1...3 Energy regeneration (5...10 seconds).'),
  (42, 'Energy Burn', 'Spell. Target foe loses 1...10 Energy and takes 9 damage for each point of Energy lost.', 'Spell. Causes 1...10 Energy loss. Deals 9 damage for each point of Energy lost.', 'Energy Burn', 'Spell. Target foe loses 1...10 Energy and takes 9 damage for each point of Energy lost.', 'Spell. Causes 1...10 Energy loss. Deals 9 damage for each point of Energy lost.'),
  (43, 'Clumsiness', 'Hex Spell. For 4 seconds, target and adjacent foes are hexed with Clumsiness. The next time each foe attacks, the attack is interrupted and that foe suffers 10...80 damage.', 'Hex Spell. (4 seconds.) Also hexes adjacent foes. Interrupts next attack. Interruption effect: deals 10...80 damage.', 'Clumsiness', 'Hex Spell. For 4 seconds, target and adjacent foes are hexed with Clumsiness. The next time each foe attacks, the attack is interrupted and that foe suffers 10...80 damage.', 'Hex Spell. (4 seconds.) Also hexes adjacent foes. Interrupts next attack. Interruption effect: deals 10...80 damage.'),
  (44, 'Phantom Pain', 'Hex Spell. For 10 seconds, target foe suffers -1...4 Health degeneration. When Phantom Pain ends, that foe suffers a Deep Wound, lowering that foe''s maximum Health by 20% for 5...20 seconds.', 'Hex Spell. (10 seconds.) Causes -1...4 Health degeneration. End effect: inflicts Deep Wound condition (5...20 seconds).', 'Phantom Pain', 'Hex Spell. For 10 seconds, target foe suffers -1...4 Health degeneration. When Phantom Pain ends, that foe suffers a Deep Wound, lowering that foe''s maximum Health by 20% for 5...20 seconds.', 'Hex Spell. (10 seconds.) Causes -1...4 Health degeneration. End effect: inflicts Deep Wound condition (5...20 seconds).'),
  (45, 'Ethereal Burden', 'Hex Spell. For 6...12 seconds, target foe moves 50% slower. When Ethereal Burden ends, you gain 10...18 Energy.', 'Hex Spell. (6...12 seconds.) Target foe moves 50% slower. End effect: you gain 10...18 Energy.', 'Ethereal Burden', 'Hex Spell. For 6...12 seconds, target foe moves 50% slower. When Ethereal Burden ends, you gain 10...18 Energy.', 'Hex Spell. (6...12 seconds.) Target foe moves 50% slower. End effect: you gain 10...18 Energy.'),
  (46, 'Guilt', 'Hex Spell. For 6 seconds, the next time target foe casts a spell that targets a foe, the spell fails and you steal up to 5...14 Energy from that foe.', 'Hex Spell. (6 seconds.) Target foe''s next spell fails and you steal 5...14 Energy. No effect unless this foe''s spell targets one of your allies.', 'Guilt', 'Hex Spell. For 6 seconds, the next time target foe casts a spell that targets a foe, the spell fails and you steal up to 5...14 Energy from that foe.', 'Hex Spell. (6 seconds.) Target foe''s next spell fails and you steal 5...14 Energy. No effect unless this foe''s spell targets one of your allies.'),
  (47, 'Ineptitude', 'Elite Hex Spell. For 4 seconds, the next time the target foe or any adjacent foe attacks, they take 30...135 damage and are Blinded for 10 seconds.', 'Elite Hex Spell. (4 seconds.) Also hexes foes adjacent to target. Deals 30...135 damage. Inflicts Blindness condition (10 seconds). No effect unless hexed foe attacks.', 'Ineptitude', 'Elite Hex Spell. For 4 seconds, the next time the target foe or any adjacent foe attacks, they take 30...135 damage and are Blinded for 10 seconds.', 'Elite Hex Spell. (4 seconds.) Also hexes foes adjacent to target. Deals 30...135 damage. Inflicts Blindness condition (10 seconds). No effect unless hexed foe attacks.'),
  (48, 'Spirit of Failure', 'Hex Spell. For 30 seconds, target foe has a 25% chance to miss with attacks. You gain 1...3 Energy whenever that foe fails to hit in combat.', 'Hex Spell. (30 seconds.) Target foe has 25% chance to miss. You gain 1...3 Energy whenever this foe misses.', 'Spirit of Failure', 'Hex Spell. For 30 seconds, target foe has a 25% chance to miss with attacks. You gain 1...3 Energy whenever that foe fails to hit in combat.', 'Hex Spell. (30 seconds.) Target foe has 25% chance to miss. You gain 1...3 Energy whenever this foe misses.'),
  (49, 'Mind Wrack', 'Hex Spell. For 5...40 seconds, whenever this foe is the target of any of your non-hex Mesmer skills, that foe loses 1 Energy and takes 5...25 damage per point of Energy lost. If the target foe''s Energy drops to 0, Mind Wrack ends and that foe takes 15...100 damage.', 'Hex Spell. (5...40 seconds.) Causes 1 Energy loss each time foe is the target of your non-hex Mesmer skills. Deals 5...25 damage per point of Energy lost. If target foe''s Energy drops to 0, it takes 15...100 damage and Mind Wrack ends.', 'Mind Wrack (PvP)', 'Hex Spell. For 5...40 seconds, whenever this foe is the target of one of your non-hex Mesmer skills, that foe loses 1 Energy. If the target foe''s Energy drops to 0, Mind Wrack ends and that foe takes 15...100 damage.', 'Hex Spell. (5...40 seconds.) Causes 1 Energy loss each time foe is the target of your non-hex Mesmer skills. If target foe''s Energy drops to 0, Mind Wrack ends and that foe takes 15...100 damage.'),
  (50, 'Wastrel''s Worry', 'Hex Spell. After 3 seconds, target foe takes 20...100 damage and all adjacent foes take 75% of that damage. If that foe successfully uses a skill, Wastrel''s Worry ends prematurely and does no damage.', 'Hex Spell. (3 seconds.) End effect: causes 20...100 damage to target and 75% of that damage to adjacent foes. No effect and ends early if target foe uses a skill.', 'Wastrel''s Worry (PvP)', 'Hex Spell. After 3 seconds, target foe takes 20...100 damage and all adjacent foes take 75% of that damage. If that foe successfully uses a skill, Wastrel''s Worry ends prematurely and does no damage.', 'Hex Spell. (3 seconds.) End effect: causes 20...100 damage to target and 75% of that damage to adjacent foes. No effect and ends early if target foe uses a skill.'),
  (51, 'Shame', 'Hex Spell. For 6 seconds, the next time target foe casts a spell that targets an ally, the spell fails and you steal up to 5...14 Energy from that foe.', 'Hex Spell. (6 seconds.) Target foe''s next spell fails and you steal 5...14 Energy. No effect unless this foe''s spell targeted one of its allies.', 'Shame', 'Hex Spell. For 6 seconds, the next time target foe casts a spell that targets an ally, the spell fails and you steal up to 5...14 Energy from that foe.', 'Hex Spell. (6 seconds.) Target foe''s next spell fails and you steal 5...14 Energy. No effect unless this foe''s spell targeted one of its allies.'),
  (52, 'Panic', 'Elite Hex Spell. For 1...10 seconds, target foe and all nearby foes are hexed with Panic. When a foe hexed with Panic successfully uses a skill, all other nearby foes are interrupted.', 'Elite Hex Spell. Also hexes foes near your target (1...10 seconds). Interrupts all other nearby foes whenever a hexed foe successfully activates a skill.', 'Panic', 'Elite Hex Spell. For 1...10 seconds, target foe and all nearby foes are hexed with Panic. When a foe hexed with Panic successfully uses a skill, all other nearby foes are interrupted.', 'Elite Hex Spell. Also hexes foes near your target (1...10 seconds). Interrupts all other nearby foes whenever a hexed foe successfully activates a skill.'),
  (53, 'Migraine', 'Elite Hex Spell. For 5...20 seconds, target foe suffers -1...8 Health degeneration and takes 100% longer to activate skills.', 'Elite Hex Spell. (5...20 seconds.) Causes -1...8 Health degeneration and doubles skill activation time.', 'Migraine (PvP)', 'Elite Hex Spell. For 4...16 seconds, target foe suffers -1...8 Health degeneration and takes 100% longer to activate skills.', 'Elite Hex Spell. (4...16 seconds.) Causes -1...8 Health degeneration and doubles skill activation time.'),
  (54, 'Crippling Anguish', 'Elite Hex Spell. For 5...20 seconds, target moves and attacks 50% slower and suffers -1...8 Health degeneration.', 'Elite Hex Spell. (5...20 seconds.) Target foe moves and attacks 50% slower and has -1...8 Health degeneration.', 'Crippling Anguish (PvP)', 'Elite Hex Spell. For 5...20 seconds, target moves 50% slower and suffers -2...6 Health degeneration.', 'Elite Hex Spell. (5...20 seconds.) Target foe moves 50% slower and has -2...6 Health degeneration.'),
  (55, 'Fevered Dreams', 'Elite Hex Spell. For 10...25 seconds, whenever target foe suffers from a new condition, all foes in the area suffer from that condition as well. If target foe has two or more conditions, that foe is Dazed for 1...3 seconds.', 'Elite Hex Spell. (10...25 seconds.) Foes in the area also have any new conditions that target foe acquires. Inflicts Dazed on target foe (1...3 seconds) if that foe has two or more conditions.', 'Fevered Dreams (PvP)', 'Elite Hex Spell. For 5...15 seconds, whenever target foe suffers from a new condition, all foes in the area suffer from that condition as well.', 'Elite Hex Spell. (5...15 seconds.) Foes in the area also have any new conditions that target foe acquires.'),
  (56, 'Soothing Images', 'Hex Spell. For 8...20 seconds, target foe and all adjacent foes cannot gain adrenaline.', 'Hex Spell. Also hexes foes adjacent to target (8...20 seconds). These foes cannot gain adrenaline.', 'Soothing Images', 'Hex Spell. For 8...20 seconds, target foe and all adjacent foes cannot gain adrenaline.', 'Hex Spell. Also hexes foes adjacent to target (8...20 seconds). These foes cannot gain adrenaline.'),
  (57, 'Cry of Frustration', 'Spell. If target foe is using a skill, that foe and all foes in the area are interrupted. Foe suffers 15...75 damage and foes in the area take 75% of that damage.', 'Spell. If target foe is using a skill, that foe and all foes in the area are interrupted. Foe suffers 15...75 damage and foes in the area take 75% of that damage.', 'Cry of Frustration', 'Spell. If target foe is using a skill, that foe and all foes in the area are interrupted. Foe suffers 15...75 damage and foes in the area take 75% of that damage.', 'Spell. If target foe is using a skill, that foe and all foes in the area are interrupted. Foe suffers 15...75 damage and foes in the area take 75% of that damage.'),
  (58, 'Signet of Midnight', 'Elite Signet. You and target touched foe become Blinded for 15 seconds.', 'Elite Touch Signet. (15 seconds.) Inflicts Blindness condition. You suffer from Blindness (15 seconds).', 'Signet of Midnight', 'Elite Signet. You and target touched foe become Blinded for 15 seconds.', 'Elite Touch Signet. (15 seconds.) Inflicts Blindness condition. You suffer from Blindness (15 seconds).'),
  (59, 'Signet of Weariness', 'Signet. Target foe and all nearby foes lose 3...8 Energy and suffer from Weakness for 1...12 seconds.', 'Signet. Also affects foes near your target. Causes 3...8 Energy loss and inflicts Weakness (1...12 seconds).', 'Signet of Weariness', 'Signet. Target foe and all nearby foes lose 3...8 Energy and suffer from Weakness for 1...12 seconds.', 'Signet. Also affects foes near your target. Causes 3...8 Energy loss and inflicts Weakness (1...12 seconds).'),
  (61, 'Leech Signet', 'Signet. Interrupt target foe''s action. If that action was a spell, you gain 3...15 Energy.', 'Signet. Interrupts an action. Interruption effect: you gain 3...15 Energy if the action was a spell.', 'Leech Signet', 'Signet. Interrupt target foe''s action. If that action was a spell, you gain 3...15 Energy.', 'Signet. Interrupts an action. Interruption effect: you gain 3...15 Energy if the action was a spell.'),
  (62, 'Signet of Humility', 'Signet. Target foe''s elite skill is disabled for 1...16 seconds. Your non-Mesmer skills are disabled for 4 seconds.', 'Signet. Disables elite skill (1...16 seconds). Disables your non-Mesmer skills (4 seconds).', 'Signet of Humility', 'Signet. Target foe''s elite skill is disabled for 1...16 seconds. Your non-Mesmer skills are disabled for 4 seconds.', 'Signet. Disables elite skill (1...16 seconds). Disables your non-Mesmer skills (4 seconds).'),
  (63, 'Keystone Signet', 'Elite Signet. All of your signets except Keystone Signet are recharged. For 20 seconds, the next 0...6 times you use a signet that targets a foe, all other foes adjacent to your target take 15...60 damage and are interrupted.', 'Elite Signet. (20 seconds.) Your next 0...6 signets interrupt and deal 15...60 damage to other foes adjacent to your target. Initial Effect: recharges all of your other signets.', 'Keystone Signet', 'Elite Signet. All of your signets except Keystone Signet are recharged. For 20 seconds, the next 0...6 times you use a signet that targets a foe, all other foes adjacent to your target take 15...60 damage and are interrupted.', 'Elite Signet. (20 seconds.) Your next 0...6 signets interrupt and deal 15...60 damage to other foes adjacent to your target. Initial Effect: recharges all of your other signets.'),
  (65, 'Arcane Mimicry', 'Spell. For 20 seconds, Arcane Mimicry becomes the non-form elite skill from target other ally.', 'Spell. This skill becomes target ally''s elite skill (20 seconds). Cannot self-target. No effect if target''s elite skill is a form.', 'Arcane Mimicry', 'Spell. For 20 seconds, Arcane Mimicry becomes the non-form elite skill from target other ally.', 'Spell. This skill becomes target ally''s elite skill (20 seconds). Cannot self-target. No effect if target''s elite skill is a form.'),
  (66, 'Spirit Shackles', 'Hex Spell. For 5...20 seconds, target foe loses 5 Energy whenever that foe attacks.', 'Hex Spell. (5...20 seconds.) Target foe loses 5 Energy whenever it attacks.', 'Spirit Shackles', 'Hex Spell. For 5...20 seconds, target foe loses 5 Energy whenever that foe attacks.', 'Hex Spell. (5...20 seconds.) Target foe loses 5 Energy whenever it attacks.'),
  (67, 'Shatter Hex', 'Spell. Remove a hex from target ally. If a hex is removed, foes near that ally take 30...120 damage.', 'Spell. Removes a hex from target ally. Removal effect: deals 30...120 damage to foes near this ally.', 'Shatter Hex', 'Spell. Remove a hex from target ally. If a hex is removed, foes near that ally take 30...120 damage.', 'Spell. Removes a hex from target ally. Removal effect: deals 30...120 damage to foes near this ally.'),
