  (74, 'Echo', 'Elite Enchantment Spell. For 30 seconds, Echo is replaced with the next skill you use. Echo acts as this skill for 30 seconds.', 'Elite Enchantment Spell. (30 seconds.) Echo becomes the next skill you use (30 seconds).', 'Echo', 'Elite Enchantment Spell. For 30 seconds, Echo is replaced with the next skill you use. Echo acts as this skill for 30 seconds.', 'Elite Enchantment Spell. (30 seconds.) Echo becomes the next skill you use (30 seconds).'),
  (75, 'Arcane Echo', 'Enchantment Spell. If you cast a spell in the next 20 seconds, Arcane Echo is replaced with that spell for 20 seconds. Arcane Echo ends prematurely if you use a non-spell skill.', 'Enchantment Spell. (20 seconds.) Arcane Echo becomes the next spell you use (20 seconds). This enchantment ends if you use any skill that is not a spell.', 'Arcane Echo', 'Enchantment Spell. If you cast a spell in the next 20 seconds, Arcane Echo is replaced with that spell for 20 seconds. Arcane Echo ends prematurely if you use a non-spell skill.', 'Enchantment Spell. (20 seconds.) Arcane Echo becomes the next spell you use (20 seconds). This enchantment ends if you use any skill that is not a spell.'),
  (76, 'Imagined Burden', 'Hex Spell. For 8...20 seconds, target foe moves 50% slower.', 'Hex Spell. (8...20 seconds.) Target foe moves 50% slower.', 'Imagined Burden', 'Hex Spell. For 8...20 seconds, target foe moves 50% slower.', 'Hex Spell. (8...20 seconds.) Target foe moves 50% slower.'),
  (77, 'Chaos Storm', 'Spell. Create a Chaos Storm at target foe''s location that lasts for 10 seconds. Each second, foes adjacent to this location take 5...25 damage and lose 0...2 Energy.', 'Spell. Deals 5...25 damage and causes 0...2 Energy loss each second (10 seconds). Hits foes adjacent to target''s initial location.', 'Chaos Storm', 'Spell. Create a Chaos Storm at target foe''s location that lasts for 10 seconds. Each second, foes adjacent to this location take 5...25 damage and lose 0...2 Energy.', 'Spell. Deals 5...25 damage and causes 0...2 Energy loss each second (10 seconds). Hits foes adjacent to target''s initial location.'),
  (78, 'Epidemic', 'Spell. Spread all negative conditions and their remaining durations from target foe to all foes adjacent to your target.', 'Spell. Conditions on target foe transfer to adjacent foes.', 'Epidemic', 'Spell. Spread all negative conditions and their remaining durations from target foe to all foes adjacent to your target.', 'Spell. Conditions on target foe transfer to adjacent foes.'),
  (79, 'Energy Drain', 'Elite Spell. Target foe loses 2...9 Energy. You gain 3 Energy for each point of Energy lost.', 'Elite Spell. Causes 2...9 Energy loss. You gain 3 Energy for each point of Energy lost.', 'Energy Drain', 'Elite Spell. Target foe loses 2...9 Energy. You gain 3 Energy for each point of Energy lost.', 'Elite Spell. Causes 2...9 Energy loss. You gain 3 Energy for each point of Energy lost.'),
