  (219, 'Obsidian Flame', 'Spell. Deal 22...112 damage to target foe. This spell ignores armor.', 'Spell. Deals 22...112 damage.', 'Obsidian Flame (PvP)', 'Spell. Deal 22...92 damage to target foe. This spell ignores armor.', 'Spell. Deals 22...92 damage.'),
  (220, 'Blinding Flash', 'Spell. Target foe is Blinded for 3...8 seconds.', 'Spell. Inflicts Blindness condition (3...8 seconds).', 'Blinding Flash', 'Spell. Target foe is Blinded for 3...8 seconds.', 'Spell. Inflicts Blindness condition (3...8 seconds).'),
  (221, 'Conjure Lightning', 'Enchantment Spell. For 60 seconds, if you''re wielding a lightning weapon, your attacks strike for an additional 5...20 lightning damage.', 'Enchantment Spell. (60 seconds.) Your attacks hit for +5...20 lightning damage. No effect unless your weapon deals lightning damage.', 'Conjure Lightning', 'Enchantment Spell. For 60 seconds, if you''re wielding a lightning weapon, your attacks strike for an additional 5...20 lightning damage.', 'Enchantment Spell. (60 seconds.) Your attacks hit for +5...20 lightning damage. No effect unless your weapon deals lightning damage.'),
  (222, 'Lightning Strike', 'Hex Spell. Strike target foe for 10...60 lightning damage. This spell has 25% armor penetration. If you are Overcast, that foe is hexed with Lightning Strike for 3 seconds. When this hex ends, that foe is struck again for 20...40 lightning damage.', 'Hex Spell. Deals 10...60 lightning damage. 25% armor penetration. Hex for 3 seconds if Overcast. End effect: deals 20...40 lightning damage.', 'Lightning Strike', 'Hex Spell. Strike target foe for 10...60 lightning damage. This spell has 25% armor penetration. If you are Overcast, that foe is hexed with Lightning Strike for 3 seconds. When this hex ends, that foe is struck again for 20...40 lightning damage.', 'Hex Spell. Deals 10...60 lightning damage. 25% armor penetration. Hex for 3 seconds if Overcast. End effect: deals 20...40 lightning damage.'),
  (223, 'Chain Lightning', 'Spell. Target foe and up to two other foes near your target are struck for 10...85 lightning damage. This spell has 25% armor penetration.', 'Spell. Deals 10...85 lightning damage. Also hits two foes near your target. 25% armor penetration.', 'Chain Lightning', 'Spell. Target foe and up to two other foes near your target are struck for 10...85 lightning damage. This spell has 25% armor penetration.', 'Spell. Deals 10...85 lightning damage. Also hits two foes near your target. 25% armor penetration.'),
