  (1043, 'Dash', 'Stance. For 3 seconds, you run 50% faster.', 'Stance. (3 seconds.) You move 50% faster.', 'Dash (PvP)', 'Stance. For 3 seconds, you run 50% faster. Every 2 points in Shadow Arts lowers recharge by 1 seconds (max 6 seconds).', 'Stance. (3 seconds.) You move 50% faster. Every 2 points in Shadow Arts lowers recharge by 1 seconds (max 6 seconds).'),
  (1044, 'Dark Prison', 'Hex Spell. Shadow Step to target foe. For 1...6 seconds, that foe moves 33% slower.', 'Hex Spell. Shadow Step to target foe. This foe moves 33% slower (1...6 seconds).', 'Dark Prison', 'Hex Spell. Shadow Step to target foe. For 1...6 seconds, that foe moves 33% slower.', 'Hex Spell. Shadow Step to target foe. This foe moves 33% slower (1...6 seconds).'),
