  (1048, 'Revealed Enchantment', 'Spell. Remove an enchantment from target foe and gain 3...15 Energy. For 20 seconds, Revealed Enchantment is replaced with the enchantment removed from target foe.', 'Spell. Removes an enchantment from target foe. Removal effects: you gain 3...15 Energy; this spell is replaced with that enchantment (20 seconds).', 'Revealed Enchantment', 'Spell. Remove an enchantment from target foe and gain 3...15 Energy. For 20 seconds, Revealed Enchantment is replaced with the enchantment removed from target foe.', 'Spell. Removes an enchantment from target foe. Removal effects: you gain 3...15 Energy; this spell is replaced with that enchantment (20 seconds).'),
  (1049, 'Revealed Hex', 'Spell. Remove a hex from target ally and gain 4...10 Energy. For 20 seconds, Revealed Hex is replaced with the hex that was removed.', 'Spell. Removes a hex from target ally. Removal effects: you gain 4...10 Energy; this spell is replaced with that hex (20 seconds).', 'Revealed Hex', 'Spell. Remove a hex from target ally and gain 4...10 Energy. For 20 seconds, Revealed Hex is replaced with the hex that was removed.', 'Spell. Removes a hex from target ally. Removal effects: you gain 4...10 Energy; this spell is replaced with that hex (20 seconds).'),
  (1052, 'Accumulated Pain', 'Spell. Target foe takes 15...75 damage. If target foe is suffering from 2 or more hexes, that foe suffers a Deep Wound for 5...20 seconds.', 'Spell. Deals 15...75 damage. Inflicts Deep Wound condition (5...20 seconds) if target foe has 2 or more hexes.', 'Accumulated Pain (PvP)', 'Spell. Target foe takes 10...35 damage. If target foe is suffering from 2 or more hexes, that foe suffers a Deep Wound for 5...20 seconds.', 'Spell. Deals 10...35 damage. Inflicts Deep Wound condition (5...20 seconds) if target foe has 2 or more hexes.'),
