  (1244, 'Ghostly Haste', 'Enchantment Spell. For 5...30 seconds, spells you cast while within earshot of a spirit recharge 25% faster.', 'Enchantment Spell. (5...30 seconds.) Spells you cast recharge 25% faster. No effect unless you are within earshot of a spirit.', 'Ghostly Haste', 'Enchantment Spell. For 5...30 seconds, spells you cast while within earshot of a spirit recharge 25% faster.', 'Enchantment Spell. (5...30 seconds.) Spells you cast recharge 25% faster. No effect unless you are within earshot of a spirit.'),
  (1245, 'Gaze from Beyond', 'Spell. Target foe is struck for 20...65 lightning damage. If you are within earshot of a spirit, that foe is Blinded for 2...6 seconds.', 'Spell. Deals 20...65 lightning damage. Inflicts Blindness condition for 2...6 seconds if you are within earshot of a spirit.', 'Gaze from Beyond', 'Spell. Target foe is struck for 20...65 lightning damage. If you are within earshot of a spirit, that foe is Blinded for 2...6 seconds.', 'Spell. Deals 20...65 lightning damage. Inflicts Blindness condition for 2...6 seconds if you are within earshot of a spirit.'),
