  (1333, 'Extend Conditions', 'Elite Spell. Spread all conditions from target foe to all foes near your target. The durations of those conditions are increased by 5...100% (maximum 30 seconds).', 'Elite Spell. Spread all conditions from target foe to all foes near your target. Those durations of those conditions are increased by 5...100% (maximum 30 seconds).', 'Extend Conditions', 'Elite Spell. Spread all conditions from target foe to all foes near your target. The durations of those conditions are increased by 5...100% (maximum 30 seconds).', 'Elite Spell. Spread all conditions from target foe to all foes near your target. Those durations of those conditions are increased by 5...100% (maximum 30 seconds).'),
  (1334, 'Hypochondria', 'Spell. Transfer all conditions from all foes in the area to target foe.', 'Spell. Transfer all conditions from foes in the area to target foe.', 'Hypochondria', 'Spell. Transfer all conditions from all foes in the area to target foe.', 'Spell. Transfer all conditions from foes in the area to target foe.'),
  (1335, 'Wastrel''s Demise', 'Hex Spell. For 5 seconds, target foe is hexed with Wastrel''s Demise. Each second while hexed, target foe and all foes adjacent to that foe take 1...10 damage and an additional 1...10 damage for each second this spell is in effect. This hex ends prematurely if target foe uses a skill.', 'Hex Spell. (5 seconds.) Each second while hexed, target foe and all foes adjacent to that foe take 1...10 damage. Foes take +1...10 damage each second this hex is in effect. Ends early if target foe uses a skill.', 'Wastrel''s Demise', 'Hex Spell. For 5 seconds, target foe is hexed with Wastrel''s Demise. Each second while hexed, target foe and all foes adjacent to that foe take 1...10 damage and an additional 1...10 damage for each second this spell is in effect. This hex ends prematurely if target foe uses a skill.', 'Hex Spell. (5 seconds.) Each second while hexed, target foe and all foes adjacent to that foe take 1...10 damage. Foes take +1...10 damage each second this hex is in effect. Ends early if target foe uses a skill.'),
  (1336, 'Spiritual Pain', 'Spell. Target foe takes 15...75 damage. All hostile summoned creatures in the area of that foe take 25...125 damage.', 'Spell. Deals 15...75 damage. Deals 25...125 damage to hostile summoned creatures in the area of target foe.', 'Spiritual Pain (PvP)', 'Spell. Target foe takes 5...40 damage. All hostile summoned creatures in the area of that foe take 25...125 damage.', 'Spell. Deals 5...40 damage. Deals 25...125 damage to hostile summoned creatures in the area of target foe.'),
  (1337, 'Drain Delusions', 'Spell. Remove one Mesmer hex from target foe. If a hex was removed in this way, that foe loses 1...5 Energy and you gain 4 Energy for each point lost.', 'Spell. Removes one Mesmer hex from target foe. Causes 1...5 Energy loss. You gain 4 Energy for each point lost. No effect unless a hex was removed.', 'Drain Delusions', 'Spell. Remove one Mesmer hex from target foe. If a hex was removed in this way, that foe loses 1...5 Energy and you gain 4 Energy for each point lost.', 'Spell. Removes one Mesmer hex from target foe. Causes 1...5 Energy loss. You gain 4 Energy for each point lost. No effect unless a hex was removed.'),
  (1338, 'Persistence of Memory', 'Enchantment Spell. For 5...20 seconds, whenever a spell you cast is interrupted, that spell is instantly recharged.', 'Enchantment Spell. (5...20 seconds.) Your interrupted spells recharge instantly.', 'Persistence of Memory', 'Enchantment Spell. For 5...20 seconds, whenever a spell you cast is interrupted, that spell is instantly recharged.', 'Enchantment Spell. (5...20 seconds.) Your interrupted spells recharge instantly.'),
  (1339, 'Symbols of Inspiration', 'Elite Skill. For 6...40 seconds, this skill becomes the Elite of target foe. Elite skills you cast use your Fast Casting attribute instead of their normal attributes.', 'Elite Skill. (6...40 seconds.) This skill becomes the Elite of target foe. Elite skills use your Fast Casting attribute instead of their normal attributes.', 'Symbols of Inspiration', 'Elite Skill. For 6...40 seconds, this skill becomes the Elite of target foe. Elite skills you cast use your Fast Casting attribute instead of their normal attributes.', 'Elite Skill. (6...40 seconds.) This skill becomes the Elite of target foe. Elite skills use your Fast Casting attribute instead of their normal attributes.'),
  (1340, 'Symbolic Celerity', 'Enchantment Spell. For 36...60 seconds, all of your signets use your Fast Casting attribute instead of their normal attributes.', 'Enchantment Spell. (36...60 seconds.) Your signets use your Fast Casting attribute.', 'Symbolic Celerity', 'Enchantment Spell. For 36...60 seconds, all of your signets use your Fast Casting attribute instead of their normal attributes.', 'Enchantment Spell. (36...60 seconds.) Your signets use your Fast Casting attribute.'),
  (1341, 'Frustration', 'Hex Spell. For 5...20 seconds, target foe casts spells 50% slower and takes 5...50 damage whenever interrupted. If a skill is interrupted, Frustration deals double damage.', 'Hex Spell. (5...20 seconds.) Causes 50% slower spell casting. Target foe takes 5...50 damage whenever interrupted. Deals double damage on skill interrupt.', 'Frustration (PvP)', 'Hex Spell. For 5...20 seconds, target foe casts spells 50% slower and takes 5...50 damage whenever interrupted.', 'Hex Spell. (5...20 seconds.) Causes 50% slower spell casting. Target foe takes 5...50 damage whenever interrupted.'),
  (1342, 'Tease', 'Elite Spell. If target foe is using a skill, that foe and other foes in the area are interrupted and you steal 0...5 Energy from all foes in the area.', 'Elite Spell. Interrupts a skill. Interruption effect: also interrupts other foes in the area, and you steal 0...5 Energy from all foes in the area.', 'Tease (PvP)', 'Elite Spell. If target foe is using a skill, that foe and other foes in the area are interrupted and you steal 0...5 Energy from all foes in the area.', 'Elite Spell. Interrupts a skill. Interruption effect: also interrupts other foes in the area, and you steal 0...5 Energy from all foes in the area.'),
  (1343, 'Ether Phantom', 'Hex Spell. For 10 seconds, target foe has -1 Energy degeneration. If this hex is removed prematurely, that foe loses 1...5 Energy.', 'Hex Spell. (10 seconds.) Causes -1 Energy degeneration. Causes 1...5 Energy loss if this hex ends early.', 'Ether Phantom', 'Hex Spell. For 10 seconds, target foe has -1 Energy degeneration. If this hex is removed prematurely, that foe loses 1...5 Energy.', 'Hex Spell. (10 seconds.) Causes -1 Energy degeneration. Causes 1...5 Energy loss if this hex ends early.'),
  (1344, 'Web of Disruption', 'Hex Spell. Interrupt target foe. For 10 seconds, target foe is hexed with Web of Disruption. When this hex ends, that foe is interrupted again.', 'Hex Spell. (10 seconds.) Initial effect: interrupts a skill. End effect: interrupts a skill.', 'Web of Disruption (PvP)', 'Hex Spell. Interrupt target foe. For 10 seconds, target foe is hexed with Web of Disruption. When this hex ends, that foe is interrupted again.', 'Hex Spell. (10 seconds.) Initial effect: interrupts a skill. End effect: interrupts a skill.'),
  (1345, 'Enchanter''s Conundrum', 'Elite Hex Spell. For 10 seconds, target foe casts enchantments 100...200% slower. If target foe is not under the effects of an enchantment when this hex is applied, that foe takes 10...100 damage and all adjacent foes take 75% of that damage.', 'Elite Hex Spell. Causes 100...200% slower enchantment casting (10 seconds). Initial effect: if target foe is not enchanted deals 10...100 damage to target and 75% of that damage to adjacent foes.', 'Enchanter''s Conundrum (PvP)', 'Elite Hex Spell. For 10 seconds, target foe casts enchantments 100...200% slower. If target foe is not under the effects of an enchantment when this hex is applied, that foe takes 10...100 damage and all adjacent foes take 75% of that damage.', 'Elite Hex Spell. Causes 100...200% slower enchantment casting (10 seconds). Initial effect: if target foe is not enchanted deals 10...100 damage to target and 75% of that damage to adjacent foes.'),
  (1346, 'Signet of Illusions', 'Elite Signet. Your next 1...3 non-Illusion spells use your Illusion attribute instead of their normal attribute.', 'Elite Signet. Your next 1...3 non-Illusion spells use your Illusion attribute instead of their normal attribute.', 'Signet of Illusions', 'Elite Signet. Your next 1...3 non-Illusion spells use your Illusion attribute instead of their normal attribute.', 'Elite Signet. Your next 1...3 non-Illusion spells use your Illusion attribute instead of their normal attribute.'),
  (1347, 'Discharge Enchantment', 'Spell. Remove one enchantment from target foe. If that foe is hexed, this skill recharges 20...50% faster.', 'Spell. Removes one enchantment from target foe. 20...50% faster recharge if that foe was hexed.', 'Discharge Enchantment', 'Spell. Remove one enchantment from target foe. If that foe is hexed, this skill recharges 20...50% faster.', 'Spell. Removes one enchantment from target foe. 20...50% faster recharge if that foe was hexed.'),
  (1348, 'Hex Eater Vortex', 'Elite Spell. Remove a hex from target ally. If a hex is removed in this way, foes in the area of that ally take 30...90 damage and lose one enchantment.', 'Elite Spell. Removes one hex from target ally. Removal effect: deals 30...90 damage and removes one enchantment from foes in the area of this ally.', 'Hex Eater Vortex', 'Elite Spell. Remove a hex from target ally. If a hex is removed in this way, foes in the area of that ally take 30...90 damage and lose one enchantment.', 'Elite Spell. Removes one hex from target ally. Removal effect: deals 30...90 damage and removes one enchantment from foes in the area of this ally.'),
  (1349, 'Mirror of Disenchantment', 'Spell. Remove one enchantment from target foe. All of that foe''s party members also lose that same enchantment.', 'Spell. Removes one enchantment from target foe. That foe''s party members also lose this enchantment.', 'Mirror of Disenchantment (PvP)', 'Spell. Remove one enchantment from target foe. All of that foe''s party members also lose that same enchantment.', 'Spell. Removes one enchantment from target foe. That foe''s party members also lose this enchantment.'),
  (1350, 'Simple Thievery', 'Elite Spell. Interrupt target foe''s action. If that action was a skill, that skill is disabled for 5...20 seconds, and Simple Thievery is replaced by that skill.', 'Elite Spell. Interrupts an action. Interruption effect: If a skill was interrupted, that skill is disabled and Simple Thievery becomes that skill (5...20 seconds).', 'Simple Thievery', 'Elite Spell. Interrupt target foe''s action. If that action was a skill, that skill is disabled for 5...20 seconds, and Simple Thievery is replaced by that skill.', 'Elite Spell. Interrupts an action. Interruption effect: If a skill was interrupted, that skill is disabled and Simple Thievery becomes that skill (5...20 seconds).'),
  (1351, 'Animate Shambling Horror', 'Spell. Exploit nearest corpse to create a level 1...17 shambling horror. When the shambling horror dies, it is replaced by a level 0...15 jagged horror that causes Bleeding with each of its attacks.', 'Spell. Creates a level 1...17 shambling horror. When the shambling horror dies, it is replaced by a level 0...15 jagged horror that causes Bleeding with each of its attacks. Exploits a fresh corpse.', 'Animate Shambling Horror', 'Spell. Exploit nearest corpse to create a level 1...17 shambling horror. When the shambling horror dies, it is replaced by a level 0...15 jagged horror that causes Bleeding with each of its attacks.', 'Spell. Creates a level 1...17 shambling horror. When the shambling horror dies, it is replaced by a level 0...15 jagged horror that causes Bleeding with each of its attacks. Exploits a fresh corpse.'),
  (1352, 'Order of Undeath', 'Elite Spell. For 5 seconds, your minions deal +3...16 damage, but you lose 2% of your maximum Health whenever one of your minions hits with an attack.', 'Elite Spell. (5 seconds). Your minions deal +3...16 damage. Minion hit effect: you lose 2% of your maximum Health.', 'Order of Undeath', 'Elite Spell. For 5 seconds, your minions deal +3...16 damage, but you lose 2% of your maximum Health whenever one of your minions hits with an attack.', 'Elite Spell. (5 seconds). Your minions deal +3...16 damage. Minion hit effect: you lose 2% of your maximum Health.'),
  (1353, 'Putrid Flesh', 'Spell. Destroy one of your target animated undead minions. All foes near that creature are Diseased for 5...15 seconds.', 'Spell. Destroys one of your undead servants. Inflicts Diseased condition (5...15 seconds) to foes near this servant.', 'Putrid Flesh', 'Spell. Destroy one of your target animated undead minions. All foes near that creature are Diseased for 5...15 seconds.', 'Spell. Destroys one of your undead servants. Inflicts Diseased condition (5...15 seconds) to foes near this servant.'),
  (1354, 'Feast for the Dead', 'Spell. Destroy target animated undead ally. All of your other animated undead allies are healed for 10...100 Health.', 'Spell. Destroys one of your undead servants. Heals your servants for 10...100.', 'Feast for the Dead', 'Spell. Destroy target animated undead ally. All of your other animated undead allies are healed for 10...100 Health.', 'Spell. Destroys one of your undead servants. Heals your servants for 10...100.'),
  (1355, 'Jagged Bones', 'Elite Enchantment Spell. For 60 seconds, whenever target undead servant dies, it is replaced by a level 0...15 jagged horror that causes Bleeding with each of its attacks.', 'Elite Enchantment Spell. (60 seconds.) When target undead servant dies, it is replaced by a level 0...15 jagged horror that inflicts Bleeding with attacks.', 'Jagged Bones', 'Elite Enchantment Spell. For 60 seconds, whenever target undead servant dies, it is replaced by a level 0...15 jagged horror that causes Bleeding with each of its attacks.', 'Elite Enchantment Spell. (60 seconds.) When target undead servant dies, it is replaced by a level 0...15 jagged horror that inflicts Bleeding with attacks.'),
  (1356, 'Contagion', 'Elite Enchantment Spell. For 60 seconds, whenever you suffer from a new condition, all foes in the area suffer from that same condition and you sacrifice 10...5% maximum Health.', 'Elite Enchantment Spell. (60 seconds.) Whenever you gain a condition, all foes in the area gain that same condition. You sacrifice 10...5% maximum Health each time this happens.', 'Contagion', 'Elite Enchantment Spell. For 60 seconds, whenever you suffer from a new condition, all foes in the area suffer from that same condition and you sacrifice 10...5% maximum Health.', 'Elite Enchantment Spell. (60 seconds.) Whenever you gain a condition, all foes in the area gain that same condition. You sacrifice 10...5% maximum Health each time this happens.'),
  (1358, 'Ulcerous Lungs', 'Hex Spell. For 10...30 seconds, target foe and all nearby foes suffer from -4 Health degeneration when Bleeding, and whenever they use a shout or chant, they Bleed for 5...20 seconds', 'Hex Spell. Also hexes foes near your target (10...30 seconds). Causes -4 Health degeneration to any of these foes that are Bleeding. Inflicts Bleeding (5...20 seconds) whenever these foes use a shout or chant.', 'Ulcerous Lungs', 'Hex Spell. For 10...30 seconds, target foe and all nearby foes suffer from -4 Health degeneration when Bleeding, and whenever they use a shout or chant, they Bleed for 5...20 seconds', 'Hex Spell. Also hexes foes near your target (10...30 seconds). Causes -4 Health degeneration to any of these foes that are Bleeding. Inflicts Bleeding (5...20 seconds) whenever these foes use a shout or chant.'),
  (1359, 'Pain of Disenchantment', 'Elite Spell. Target foe loses 1...3 enchantments. If an enchantment was lost in this way, that foe and all adjacent foes lose 10...100 Health.', 'Elite Spell. Target foe loses 1...3 enchantments. Removal effect: that foe and all adjacent foes lose 10...100 Health.', 'Pain of Disenchantment', 'Elite Spell. Target foe loses 1...3 enchantments. If an enchantment was lost in this way, that foe and all adjacent foes lose 10...100 Health.', 'Elite Spell. Target foe loses 1...3 enchantments. Removal effect: that foe and all adjacent foes lose 10...100 Health.'),
  (1360, 'Mark of Fury', 'Hex Spell. For 5 seconds, allies hitting target foe gain 0...2 strikes of adrenaline. When this hex ends, that foe suffers from Cracked Armor for 1...15 seconds.', 'Hex Spell. (5 seconds.) Allies hitting target foe gain 0...2 strikes of adrenaline. End effect: inflicts Cracked Armor (1...15 seconds).', 'Mark of Fury', 'Hex Spell. For 5 seconds, allies hitting target foe gain 0...2 strikes of adrenaline. When this hex ends, that foe suffers from Cracked Armor for 1...15 seconds.', 'Hex Spell. (5 seconds.) Allies hitting target foe gain 0...2 strikes of adrenaline. End effect: inflicts Cracked Armor (1...15 seconds).'),
  (1362, 'Corrupt Enchantment', 'Elite Hex Spell. Remove one enchantment from target foe. If an enchantment is removed in this way, that foe suffers from -1...8 Health degeneration for 10 seconds.', 'Elite Hex Spell. Removes one enchantment from target foe. Removal effect: -1...8 Health degeneration (10 seconds).', 'Corrupt Enchantment', 'Elite Hex Spell. Remove one enchantment from target foe. If an enchantment is removed in this way, that foe suffers from -1...8 Health degeneration for 10 seconds.', 'Elite Hex Spell. Removes one enchantment from target foe. Removal effect: -1...8 Health degeneration (10 seconds).'),
  (1363, 'Signet of Sorrow', 'Signet. Target foe takes 15...75 damage. If target foe is near a corpse or has a dead pet, this skill recharges instantly.', 'Signet. Deals 15...75 damage. Recharges instantly if target foe is near a corpse or has a dead pet.', 'Signet of Sorrow', 'Signet. Target foe takes 15...75 damage. If target foe is near a corpse or has a dead pet, this skill recharges instantly.', 'Signet. Deals 15...75 damage. Recharges instantly if target foe is near a corpse or has a dead pet.'),
  (1364, 'Signet of Suffering', 'Elite Signet. You suffer from Bleeding for 6 seconds. The next Necromancer skill that targets a foe causes Bleeding for 2...16 seconds.', 'Elite Signet. You Bleed for 6 seconds. Applies Bleeding (2...16 seconds) to the target of your next Necromancer skill.', 'Signet of Suffering', 'Elite Signet. You suffer from Bleeding for 6 seconds. The next Necromancer skill that targets a foe causes Bleeding for 2...16 seconds.', 'Elite Signet. You Bleed for 6 seconds. Applies Bleeding (2...16 seconds) to the target of your next Necromancer skill.'),
  (1365, 'Signet of Lost Souls', 'Signet. If target foe is below 50% Health, you gain 10...100 Health and 1...10 Energy.', 'Signet. You gain 10...100 Health and 1...10 Energy if target foe is below 50% Health.', 'Signet of Lost Souls', 'Signet. If target foe is below 50% Health, you gain 10...100 Health and 1...10 Energy.', 'Signet. You gain 10...100 Health and 1...10 Energy if target foe is below 50% Health.'),
  (1366, 'Well of Darkness', 'Well Spell. Exploit nearest corpse or sacrifice 66% health to create a Well of Darkness for 5...50 seconds. Hexed foes within the Well of Darkness miss 50% of the time.', 'Well Spell. (5...50 seconds.) Hexed foes in this well have 50% chance to miss. Exploits a fresh corpse or sacrifices 66% health.', 'Well of Darkness', 'Well Spell. Exploit nearest corpse or sacrifice 66% health to create a Well of Darkness for 5...50 seconds. Hexed foes within the Well of Darkness miss 50% of the time.', 'Well Spell. (5...50 seconds.) Hexed foes in this well have 50% chance to miss. Exploits a fresh corpse or sacrifices 66% health.'),
  (1367, 'Blinding Surge', 'Elite Spell. Target foe is struck for 5...50 lightning damage. That foe and all adjacent foes are Blinded for 3...8 seconds. This spell has 25% armor penetration. If this spell strikes an attacking foe, all adjacent foes are also struck and this spell deals 50% more damage.', 'Elite Spell. Deals 5...50 lightning damage. Inflicts Blind on target and adjacent foes (3...8 seconds). 25% armor penetration. If target was attacking, also hits adjacent foes and deals 50% more damage.', 'Blinding Surge', 'Elite Spell. Target foe is struck for 5...50 lightning damage. That foe and all adjacent foes are Blinded for 3...8 seconds. This spell has 25% armor penetration. If this spell strikes an attacking foe, all adjacent foes are also struck and this spell deals 50% more damage.', 'Elite Spell. Deals 5...50 lightning damage. Inflicts Blind on target and adjacent foes (3...8 seconds). 25% armor penetration. If target was attacking, also hits adjacent foes and deals 50% more damage.'),
  (1368, 'Chilling Winds', 'Hex Spell. Target foe and all adjacent foes are struck for 30...60 cold damage. For 10 seconds, the next Water Magic hex targeting a hexed foe lasts 25...100% longer.', 'Hex Spell. (10 seconds.) The next water hex on target foe lasts 25...100% longer. Initial effect: 30...60 cold damage. Also strikes adjacent.', 'Chilling Winds', 'Hex Spell. Target foe and all adjacent foes are struck for 30...60 cold damage. For 10 seconds, the next Water Magic hex targeting a hexed foe lasts 25...100% longer.', 'Hex Spell. (10 seconds.) The next water hex on target foe lasts 25...100% longer. Initial effect: 30...60 cold damage. Also strikes adjacent.'),
  (1369, 'Lightning Bolt', 'Spell. Send out a Lightning Bolt that strikes for 5...50 lightning damage if it hits. If Lightning Bolt strikes a moving foe, that foe is struck for 5...50 additional lightning damage. This spell has 25% armor penetration.', 'Spell. Projectile: deals 5...50 lightning damage. Deals 5...50 more lightning damage if target foe is moving. 25% armor penetration.', 'Lightning Bolt', 'Spell. Send out a Lightning Bolt that strikes for 5...50 lightning damage if it hits. If Lightning Bolt strikes a moving foe, that foe is struck for 5...50 additional lightning damage. This spell has 25% armor penetration.', 'Spell. Projectile: deals 5...50 lightning damage. Deals 5...50 more lightning damage if target foe is moving. 25% armor penetration.'),
  (1370, 'Storm Djinn''s Haste', 'Enchantment Spell. For 10...25 seconds, you move 25% faster. Each second that you are moving, you lose 1 Energy.', 'Enchantment Spell. (10...25 seconds.) You move 25% faster. Lose 1 Energy each second while moving.', 'Storm Djinn''s Haste', 'Enchantment Spell. For 10...25 seconds, you move 25% faster. Each second that you are moving, you lose 1 Energy.', 'Enchantment Spell. (10...25 seconds.) You move 25% faster. Lose 1 Energy each second while moving.'),
  (1371, 'Stone Striker', 'Enchantment Spell. For 5...30 seconds, whenever you take or deal elemental or physical damage, that damage is converted to earth damage.', 'Enchantment Spell. (5...30 seconds.) Converts elemental and physical damage you take or deal to earth damage.', 'Stone Striker', 'Enchantment Spell. For 5...30 seconds, whenever you take or deal elemental or physical damage, that damage is converted to earth damage.', 'Enchantment Spell. (5...30 seconds.) Converts elemental and physical damage you take or deal to earth damage.'),
  (1372, 'Sandstorm', 'Elite Spell. Create a Sandstorm at target foe''s location. For 10 seconds, nearby foes are struck for 20...40 earth damage each second and attacking foes are struck for an additional 10...30 earth damage each second.', 'Elite Spell. Deals 20...40 earth damage each second (10 seconds). Hits foes near target foe''s initial location. Hits attacking foes for 10...30 more earth damage each second.', 'Sandstorm', 'Elite Spell. Create a Sandstorm at target foe''s location. For 10 seconds, nearby foes are struck for 20...40 earth damage each second and attacking foes are struck for an additional 10...30 earth damage each second.', 'Elite Spell. Deals 20...40 earth damage each second (10 seconds). Hits foes near target foe''s initial location. Hits attacking foes for 10...30 more earth damage each second.'),
  (1373, 'Stone Sheath', 'Elite Enchantment Spell. For 5...20 seconds, you and target ally have +1...30 armor and are immune to critical hits. When you cast this spell, all foes near you and your target take 15...70 earth damage and are Weakened for 5...20 seconds.', 'Elite Enchantment Spell. (5...20 seconds.) Gives you and target ally +1...30 armor and immunity to critical hits. Initial effect: Foes near you and target ally are struck for 15...70 earth damage and are Weakened (5...20 seconds).', 'Stone Sheath', 'Elite Enchantment Spell. For 5...20 seconds, you and target ally have +1...30 armor and are immune to critical hits. When you cast this spell, all foes near you and your target take 15...70 earth damage and are Weakened for 5...20 seconds.', 'Elite Enchantment Spell. (5...20 seconds.) Gives you and target ally +1...30 armor and immunity to critical hits. Initial effect: Foes near you and target ally are struck for 15...70 earth damage and are Weakened (5...20 seconds).'),
  (1374, 'Ebon Hawk', 'Spell. Send a projectile that strikes target foe for 10...85 earth damage and causes Weakness for 5...15 seconds if it hits.', 'Spell. Projectile: deals 10...85 earth damage and inflicts Weakness condition (5...15 seconds).', 'Ebon Hawk', 'Spell. Send a projectile that strikes target foe for 10...85 earth damage and causes Weakness for 5...15 seconds if it hits.', 'Spell. Projectile: deals 10...85 earth damage and inflicts Weakness condition (5...15 seconds).'),
  (1375, 'Stoneflesh Aura', 'Enchantment Spell. For 5...15 seconds, damage you receive is reduced by 1...31, and you are immune to critical attacks.', 'Enchantment Spell. (5...15 seconds.) Reduces damage you take by 1...31, and you are immune to critical hits.', 'Stoneflesh Aura', 'Enchantment Spell. For 5...15 seconds, damage you receive is reduced by 1...31, and you are immune to critical attacks.', 'Enchantment Spell. (5...15 seconds.) Reduces damage you take by 1...31, and you are immune to critical hits.'),
  (1376, 'Glyph of Restoration', 'Glyph. For 15 seconds, your next 2 spells heal you for 30...105 Health, and you are healed for 150...400% of the Energy cost of each spell.', 'Glyph. (15 seconds.) Your next 2 spells heal you for 30...105, and you are healed for 150...400% of the Energy cost of each spell.', 'Glyph of Restoration', 'Glyph. For 15 seconds, your next 2 spells heal you for 30...105 Health, and you are healed for 150...400% of the Energy cost of each spell.', 'Glyph. (15 seconds.) Your next 2 spells heal you for 30...105, and you are healed for 150...400% of the Energy cost of each spell.'),
  (1377, 'Ether Prism', 'Elite Skill. For 3 seconds, all damage you take is reduced by 75%. When Ether Prism ends, you gain 5...20 Energy.', 'Elite Skill. (3 seconds.) All damage you take is reduced by 75%. End effect: gain 5...20 Energy.', 'Ether Prism', 'Elite Skill. For 3 seconds, all damage you take is reduced by 75%. When Ether Prism ends, you gain 5...20 Energy.', 'Elite Skill. (3 seconds.) All damage you take is reduced by 75%. End effect: gain 5...20 Energy.'),
  (1378, 'Master of Magic', 'Elite Enchantment Spell. For 1...61 seconds, all of your elemental attributes are set to 8...14, and your elemental spells return 1 Energy plus 30% of their cost.', 'Elite Enchantment Spell. (1...61 seconds). Your elemental attributes are set to 8...14 and elemental spells return 1 Energy plus 30% of their cost.', 'Master of Magic', 'Elite Enchantment Spell. For 1...61 seconds, all of your elemental attributes are set to 8...14, and your elemental spells return 1 Energy plus 30% of their cost.', 'Elite Enchantment Spell. (1...61 seconds). Your elemental attributes are set to 8...14 and elemental spells return 1 Energy plus 30% of their cost.'),
  (1379, 'Glowing Gaze', 'Spell. Target foe takes 5...50 fire damage. If that foe is on Fire, you gain 5 Energy plus 1 Energy for every 2 ranks of Energy Storage.', 'Spell. Deals 5...50 fire damage. You gain 5 Energy plus 1 Energy for every 2 ranks of Energy Storage if target foe is Burning.', 'Glowing Gaze', 'Spell. Target foe takes 5...50 fire damage. If that foe is on Fire, you gain 5 Energy plus 1 Energy for every 2 ranks of Energy Storage.', 'Spell. Deals 5...50 fire damage. You gain 5 Energy plus 1 Energy for every 2 ranks of Energy Storage if target foe is Burning.'),
  (1380, 'Savannah Heat', 'Elite Spell. You create Savannah Heat at target foe''s location. For 5 seconds, all nearby foes take 5...20 fire damage for each second this spell has been in effect.', 'Elite Spell. Deals 5...20 fire damage for each second since casting this spell (5 seconds). Hits foes near target''s initial location.', 'Savannah Heat (PvP)', 'Elite Spell. You create Savannah Heat at target foe''s location. For 5 seconds, all nearby foes take 5...20 fire damage for each second this spell has been in effect.', 'Elite Spell. Deals 5...20 fire damage for each second since casting this spell (5 seconds). Hits foes near target''s initial location.'),
  (1381, 'Flame Djinn''s Haste', 'Enchantment Spell. All adjacent foes are struck for 15...120 fire damage. For 8...14 seconds, you move 25% faster. Flame Djinn''s Haste recharges 50% faster if a foe was struck by this spell.', 'Enchantment Spell. (8...14 seconds.) You move 25% faster. Initial effect: deals 15...120 fire damage to foes adjacent to you. If you damage a foe with this spell, it recharges 50% faster.', 'Flame Djinn''s Haste', 'Enchantment Spell. All adjacent foes are struck for 15...120 fire damage. For 8...14 seconds, you move 25% faster. Flame Djinn''s Haste recharges 50% faster if a foe was struck by this spell.', 'Enchantment Spell. (8...14 seconds.) You move 25% faster. Initial effect: deals 15...120 fire damage to foes adjacent to you. If you damage a foe with this spell, it recharges 50% faster.'),
  (1382, 'Freezing Gust', 'Hex Spell. If target foe is under the effect of a Water Magic hex, that foe is struck for 20...80 cold damage. Otherwise, that foe moves 66% slower for 1...5 seconds.', 'Hex Spell. Deals 20...80 cold damage if target foe is hexed with Water Magic. Otherwise, this foe moves 66% slower (1...5 seconds).', 'Freezing Gust', 'Hex Spell. If target foe is under the effect of a Water Magic hex, that foe is struck for 20...80 cold damage. Otherwise, that foe moves 66% slower for 1...5 seconds.', 'Hex Spell. Deals 20...80 cold damage if target foe is hexed with Water Magic. Otherwise, this foe moves 66% slower (1...5 seconds).'),
  (1390, 'Judge''s Intervention', 'Enchantment Spell. For 10 seconds, the next time target ally receives damage that would be fatal, the damage is negated and one nearby foe takes 30...180 holy damage.', 'Enchantment Spell. (10 seconds.) Negates the next fatal damage. Negation effect: deals 30...180 holy damage to one foe near target ally.', 'Judge''s Intervention', 'Enchantment Spell. For 10 seconds, the next time target ally receives damage that would be fatal, the damage is negated and one nearby foe takes 30...180 holy damage.', 'Enchantment Spell. (10 seconds.) Negates the next fatal damage. Negation effect: deals 30...180 holy damage to one foe near target ally.'),
  (1391, 'Supportive Spirit', 'Enchantment Spell. For 5...23 seconds, whenever target ally takes damage while knocked down, that ally is healed for 5...50 Health.', 'Enchantment Spell. (5...23 seconds.) Heals for 5...50 whenever target ally takes damage while knocked-down.', 'Supportive Spirit', 'Enchantment Spell. For 5...23 seconds, whenever target ally takes damage while knocked down, that ally is healed for 5...50 Health.', 'Enchantment Spell. (5...23 seconds.) Heals for 5...50 whenever target ally takes damage while knocked-down.'),
