  (1395, 'Balthazar''s Pendulum', 'Elite Enchantment Spell. For 5...25 seconds, the next time target ally would be knocked down by a foe, that foe is knocked down instead.', 'Elite Enchantment Spell. (5...25 seconds.) Causes knock-down to the next foe attempting to knock-down target ally.', 'Balthazar''s Pendulum', 'Elite Enchantment Spell. For 5...25 seconds, the next time target ally would be knocked down by a foe, that foe is knocked down instead.', 'Elite Enchantment Spell. (5...25 seconds.) Causes knock-down to the next foe attempting to knock-down target ally.'),
  (1396, 'Words of Comfort', 'Spell. Target ally is healed for 20...65 Health and an additional 20...50 Health if that ally is suffering from a condition.', 'Spell. Heals for 20...65. Heals for 20...50 more if target ally has a condition.', 'Words of Comfort', 'Spell. Target ally is healed for 20...65 Health and an additional 20...50 Health if that ally is suffering from a condition.', 'Spell. Heals for 20...65. Heals for 20...50 more if target ally has a condition.'),
  (1397, 'Light of Deliverance', 'Elite Spell. All party members are healed for 5...70 Health.', 'Elite Spell. Heals entire party for 5...70.', 'Light of Deliverance (PvP)', 'Elite Spell. All party members are healed for 5...70 Health. All your Smiting Prayers are disabled for 20 seconds.', 'Elite Spell. Heals entire party for 5...70. Disables your Smiting Prayers (20 seconds).'),
  (1398, 'Scourge Enchantment', 'Hex Spell. For 30 seconds, each time target foe is the target of an enchantment, the caster of that enchantment takes 15...75 damage.', 'Hex Spell. (30 seconds.) Deals 15...75 damage to anyone casting an enchantment on target foe.', 'Scourge Enchantment', 'Hex Spell. For 30 seconds, each time target foe is the target of an enchantment, the caster of that enchantment takes 15...75 damage.', 'Hex Spell. (30 seconds.) Deals 15...75 damage to anyone casting an enchantment on target foe.'),
  (1399, 'Shield of Absorption', 'Enchantment Spell. For 3...7 seconds, damage received by target ally is reduced by 5 each time that ally is hit while under the effects of this enchantment.', 'Enchantment Spell. (3...7 seconds.) Reduces incoming damage by 5 each time target ally takes damage.', 'Shield of Absorption', 'Enchantment Spell. For 3...7 seconds, damage received by target ally is reduced by 5 each time that ally is hit while under the effects of this enchantment.', 'Enchantment Spell. (3...7 seconds.) Reduces incoming damage by 5 each time target ally takes damage.'),
  (1400, 'Reversal of Damage', 'Enchantment Spell. For 8 seconds, the next time target ally would take damage, the foe dealing the damage takes that damage instead (maximum 5...75).', 'Enchantment Spell. (8 seconds.) Negates the next damage and hits the source for that same amount (maximum 5...75).', 'Reversal of Damage', 'Enchantment Spell. For 8 seconds, the next time target ally would take damage, the foe dealing the damage takes that damage instead (maximum 5...75).', 'Enchantment Spell. (8 seconds.) Negates the next damage and hits the source for that same amount (maximum 5...75).'),
