  (1476, 'Tripwire', 'Trap. When Tripwire is triggered, all nearby foes are struck for 5...20 piercing damage. Any Crippled foes are knocked down. Tripwire ends after 90 seconds. While activating this skill, you are easily interrupted.', 'Trap. (90 seconds.) Deals 5...20 piercing damage to nearby foes. Causes knock-down to Crippled foes. Easily interrupted.', 'Tripwire', 'Trap. When Tripwire is triggered, all nearby foes are struck for 5...20 piercing damage. Any Crippled foes are knocked down. Tripwire ends after 90 seconds. While activating this skill, you are easily interrupted.', 'Trap. (90 seconds.) Deals 5...20 piercing damage to nearby foes. Causes knock-down to Crippled foes. Easily interrupted.'),
  (1478, 'Renewing Surge', 'Hex Spell. For 8 seconds, target foe suffers 2...12 damage each second. When this hex ends, you gain 1...8 Energy.', 'Hex Spell. (8 seconds.) Deals 2...12 damage each second. End effect: You gain 1...8 Energy.', 'Renewing Surge', 'Hex Spell. For 8 seconds, target foe suffers 2...12 damage each second. When this hex ends, you gain 1...8 Energy.', 'Hex Spell. (8 seconds.) Deals 2...12 damage each second. End effect: You gain 1...8 Energy.'),
  (1479, 'Offering of Spirit', 'Elite Spell. Gain 8...17 Energy. If any spirits are within earshot, you do not sacrifice Health.', 'Elite Spell. You gain 8...17 Energy. You do not sacrifice Health if any spirits are within earshot.', 'Offering of Spirit', 'Elite Spell. Gain 8...17 Energy. If any spirits are within earshot, you do not sacrifice Health.', 'Elite Spell. You gain 8...17 Energy. You do not sacrifice Health if any spirits are within earshot.'),
  (1480, 'Spirit''s Gift', 'Enchantment Spell. For 60 seconds, whenever you create a creature, all allies near that creature gain 5...50 Health and lose 1 condition.', 'Enchantment Spell. (60 seconds.) Whenever you create a creature, all nearby allies gain 5...50 Health and lose one condition.', 'Spirit''s Gift', 'Enchantment Spell. For 60 seconds, whenever you create a creature, all allies near that creature gain 5...50 Health and lose 1 condition.', 'Enchantment Spell. (60 seconds.) Whenever you create a creature, all nearby allies gain 5...50 Health and lose one condition.'),
  (1481, 'Death Pact Signet', 'Signet. Resurrect target party member with your current Health and 15...100% maximum Energy. The next time that ally dies within 120 seconds, so do you.', 'Signet. Resurrects target party member with your current Health and 15...100% maximum Energy. For 120 seconds, you die the next time this party member dies.', 'Death Pact Signet (PvP)', 'Signet. Resurrect target party member with your current Health and 15...100% maximum Energy. The next time that ally dies within 120 seconds, so do you.', 'Signet. Resurrects target party member with your current Health and 15...100% maximum Energy. For 120 seconds, you die the next time this party member dies.'),
  (1482, 'Reclaim Essence', 'Elite Spell. All of your spirits die. You gain 5...20 Energy and all of your Binding Rituals are recharged if a spirit died in this way.', 'Elite Spell. All of your Spirits die. If a Spirit dies in this way, you gain 5...20 Energy and all of your Binding Rituals are recharged.', 'Reclaim Essence', 'Elite Spell. All of your spirits die. You gain 5...20 Energy and all of your Binding Rituals are recharged if a spirit died in this way.', 'Elite Spell. All of your Spirits die. If a Spirit dies in this way, you gain 5...20 Energy and all of your Binding Rituals are recharged.'),
  (1483, 'Banishing Strike', 'Melee Attack. If it hits, this attack deals 10...60 holy damage. It deals double damage to summoned creatures.', 'Melee Attack. Deals 10...60 holy damage. Deals double damage to summoned creatures.', 'Banishing Strike (PvP)', 'Melee Attack. If it hits, this attack deals 10...60 holy damage. It deals double damage to summoned creatures.', 'Melee Attack. Deals 10...60 holy damage. Deals double damage to summoned creatures.'),
  (1484, 'Mystic Sweep', 'Melee Attack. If this attack hits, you deal +3...12 damage. If you are enchanted, this attack deals an additional +3...12 damage.', 'Melee Attack. Deals +3...12 damage. Deals an additional +3...12 damage if you are enchanted.', 'Mystic Sweep', 'Melee Attack. If this attack hits, you deal +3...12 damage. If you are enchanted, this attack deals an additional +3...12 damage.', 'Melee Attack. Deals +3...12 damage. Deals an additional +3...12 damage if you are enchanted.'),
  (1485, 'Eremite''s Attack', 'Scythe Attack. If it hits, this attack deals +1...10 damage and removes a Dervish enchantment. If an enchantment is removed, you do an additional +1...10 damage and strike all adjacent foes.', 'Scythe Attack. Deals +1...10 damage and removes a Dervish enchantment. Removal Effect: deals +1...10 more damage and strikes all adjacent foes.', 'Eremite''s Attack', 'Scythe Attack. If it hits, this attack deals +1...10 damage and removes a Dervish enchantment. If an enchantment is removed, you do an additional +1...10 damage and strike all adjacent foes.', 'Scythe Attack. Deals +1...10 damage and removes a Dervish enchantment. Removal Effect: deals +1...10 more damage and strikes all adjacent foes.'),
  (1486, 'Reap Impurities', 'Melee Attack. If this attack hits, you deal +3...15 damage. Each foe you hit loses 1 condition. For each foe who loses a condition, all foes adjacent to that target foe take 10...40 holy damage.', 'Melee Attack. Deals +3...15 damage. Struck foes lose 1 condition. Removal Effect: All foes adjacent to those struck take 10...40 holy damage.', 'Reap Impurities', 'Melee Attack. If this attack hits, you deal +3...15 damage. Each foe you hit loses 1 condition. For each foe who loses a condition, all foes adjacent to that target foe take 10...40 holy damage.', 'Melee Attack. Deals +3...15 damage. Struck foes lose 1 condition. Removal Effect: All foes adjacent to those struck take 10...40 holy damage.'),
  (1487, 'Twin Moon Sweep', 'Melee Attack. You lose 1 Dervish enchantment and gain 10...50 Health. If an enchantment is lost in this way, you cannot be blocked, you strike twice, and you gain an additional 10...70 Health.', 'Melee Attack. Remove 1 of your Dervish enchantments. Gain 10...50 Health. Removal effect: unblockable, attack twice, and gain 10...70 more Health.', 'Twin Moon Sweep (PvP)', 'Melee Attack. You lose 1 Dervish enchantment and gain 10...20 Health. If an enchantment is lost in this way, you cannot be blocked, you strike twice, with each strike doing 25% less damage than normal, and you gain an additional 10...30 Health.', 'Melee Attack. Remove 1 of your Dervish enchantments. Gain 10...20 Health. Removal effect: unblockable, attack twice, each strike doing 25% less damage, and gain 10...30 more Health.'),
  (1488, 'Victorious Sweep', 'Melee Attack. If this attack hits, you deal +5...25 damage. If target foe has less Health than you, you gain 30...80 Health.', 'Melee Attack. Deals +5...25 damage. You gain 30...80 Health for each foe you hit that has less Health than you.', 'Victorious Sweep', 'Melee Attack. If this attack hits, you deal +5...25 damage. If target foe has less Health than you, you gain 30...80 Health.', 'Melee Attack. Deals +5...25 damage. You gain 30...80 Health for each foe you hit that has less Health than you.'),
  (1489, 'Irresistible Sweep', 'Scythe Attack. Deal +3...15 damage and lose 1 Dervish enchantment. If you lose an enchantment in this way, Irresistible Sweep cannot be blocked, removes a stance, and deals +3...15 additional damage.', 'Scythe Attack. Deals +3...15 damage. Remove 1 of your Dervish enchantments. Removal effect: unblockable, removes a stance, deals +3...15 additional damage.', 'Irresistible Sweep (PvP)', 'Scythe Attack. Deal +3...15 damage and lose 1 Dervish enchantment. If you lose an enchantment in this way, Irresistible Sweep cannot be blocked and removes a stance.', 'Scythe Attack. Deals +3...15 damage. Remove 1 of your Dervish enchantments. Removal effect: unblockable, removes a stance.'),
  (1490, 'Pious Assault', 'Melee Attack. If it hits, this attack deals +10...20 damage and removes 1 Dervish enchantment. If a Dervish enchantment was removed, this skill recharges 75% faster and adjacent foes take 15...40 damage.', 'Melee Attack. Deals +10...20 damage. Removes 1 of your Dervish enchantments. Removal Effect: this skill recharges 75% faster and adjacent foes take 15...40 damage.', 'Pious Assault (PvP)', 'Melee Attack. You remove 1 Dervish enchantment. If a Dervish enchantment was removed, this skill recharges 75% faster and adjacent foes take 15...40 damage.', 'Melee Attack. Removes 1 of your Dervish enchantments. Removal Effect: this skill recharges 75% faster and adjacent foes take 15...40 damage.'),
  (1491, 'Mystic Twister', 'Spell. Deals 10...60 cold damage to all nearby foes. If you are enchanted, this spell deals an additional 10...60 cold damage.', 'Spell. Deals 10...60 cold damage to all nearby foes. Deals 10...60 more cold damage if you are enchanted.', 'Mystic Twister', 'Spell. Deals 10...60 cold damage to all nearby foes. If you are enchanted, this spell deals an additional 10...60 cold damage.', 'Spell. Deals 10...60 cold damage to all nearby foes. Deals 10...60 more cold damage if you are enchanted.'),
  (1493, 'Grenth''s Fingers', 'Flash Enchantment Spell. All nearby foes are struck for 10...40 cold damage. For 30 seconds, your attacks deal cold damage. When this enchantment ends, you transfer 1...2 conditions to all nearby foes.', 'Flash Enchantment Spell. (30 seconds.) Your attacks deal cold damage. Initial effect: hits nearby foes for 10...40 cold damage. End effect: transfers 1...2 conditions to all nearby foes.', 'Grenth''s Fingers', 'Flash Enchantment Spell. All nearby foes are struck for 10...40 cold damage. For 30 seconds, your attacks deal cold damage. When this enchantment ends, you transfer 1...2 conditions to all nearby foes.', 'Flash Enchantment Spell. (30 seconds.) Your attacks deal cold damage. Initial effect: hits nearby foes for 10...40 cold damage. End effect: transfers 1...2 conditions to all nearby foes.'),
  (1495, 'Aura of Thorns', 'Flash Enchantment Spell. All nearby foes begin Bleeding for 5...15 seconds. For 30 seconds, this enchantment does nothing. When this enchantment ends, all nearby foes are Crippled for 3...8 seconds.', 'Flash Enchantment Spell. (30 seconds.) Initial effect: inflicts Bleeding condition (5...15 seconds) on nearby foes. End effect: inflicts Crippled condition (3...8 seconds) on nearby foes.', 'Aura of Thorns (PvP)', 'Flash Enchantment Spell. All nearby foes begin Bleeding for 5...15 seconds. For 30 seconds, this enchantment does nothing. When this enchantment ends, all nearby foes are Crippled for 3...8 seconds.', 'Flash Enchantment Spell. (30 seconds.) Initial effect: inflicts Bleeding condition (5...15 seconds) on nearby foes. End effect: inflicts Crippled condition (3...8 seconds) on nearby foes.'),
  (1496, 'Balthazar''s Rage', 'Flash Enchantment Spell. All nearby foes are set on fire for 1...3 seconds. For 20 seconds afterward, this enchantment does nothing. When this enchantment ends, you gain 1...2 strikes of adrenaline if any foes are within earshot.', 'Flash Enchantment Spell. (20 seconds.) Initial Effect: inflicts Burning (1...3 seconds) on nearby foes. End Effect: gain 1...2 strikes of adrenaline if any foes are in earshot.', 'Balthazar''s Rage', 'Flash Enchantment Spell. All nearby foes are set on fire for 1...3 seconds. For 20 seconds afterward, this enchantment does nothing. When this enchantment ends, you gain 1...2 strikes of adrenaline if any foes are within earshot.', 'Flash Enchantment Spell. (20 seconds.) Initial Effect: inflicts Burning (1...3 seconds) on nearby foes. End Effect: gain 1...2 strikes of adrenaline if any foes are in earshot.'),
  (1497, 'Dust Cloak', 'Flash Enchantment Spell. All nearby foes are struck for 10...40 earth damage. For 30 seconds, your attacks deal earth damage. When this enchantment ends, all nearby foes are Blinded for 1...4 seconds.', 'Flash Enchantment Spell. (30 seconds.) Your attacks deal earth damage. Initial effect: deals 10...40 earth damage to nearby foes. End effect: inflicts Blindness condition (1...4 seconds) on nearby foes.', 'Dust Cloak (PvP)', 'Flash Enchantment Spell. All nearby foes are struck for 10...40 earth damage. For 30 seconds, your attacks deal earth damage. When this enchantment ends, all nearby foes are Blinded for 1...4 seconds.', 'Flash Enchantment Spell. (30 seconds.) Your attacks deal earth damage. Initial effect: deals 10...40 earth damage to nearby foes. End effect: inflicts Blindness condition (1...4 seconds) on nearby foes.'),
  (1498, 'Staggering Force', 'Flash Enchantment Spell. All nearby foes are struck for 10...40 earth damage. For 30 seconds, your attacks deal earth damage. When this enchantment ends, all nearby foes have Cracked Armor for 1...10 seconds.', 'Flash Enchantment Spell. (30 seconds.) Your attacks deal earth damage. Initial effect: deals 10...40 earth damage to nearby foes. End effect: inflicts Cracked Armor (1...10 seconds) on nearby foes.', 'Staggering Force', 'Flash Enchantment Spell. All nearby foes are struck for 10...40 earth damage. For 30 seconds, your attacks deal earth damage. When this enchantment ends, all nearby foes have Cracked Armor for 1...10 seconds.', 'Flash Enchantment Spell. (30 seconds.) Your attacks deal earth damage. Initial effect: deals 10...40 earth damage to nearby foes. End effect: inflicts Cracked Armor (1...10 seconds) on nearby foes.'),
  (1499, 'Pious Renewal', 'Elite Flash Enchantment Spell. For 8 seconds, nothing happens. When this enchantment ends, Pious Renewal is recharged and you gain 0...5 Energy and 0...30 Health.', 'Elite Flash Enchantment Spell. (8 seconds.) End Effect: recharges itself and you gain 0...5 Energy and 0...30 Health.', 'Pious Renewal', 'Elite Flash Enchantment Spell. For 8 seconds, nothing happens. When this enchantment ends, Pious Renewal is recharged and you gain 0...5 Energy and 0...30 Health.', 'Elite Flash Enchantment Spell. (8 seconds.) End Effect: recharges itself and you gain 0...5 Energy and 0...30 Health.'),
  (1500, 'Mirage Cloak', 'Flash Enchantment Spell. For 20 seconds, you have a 40% chance to block and an extra 4...10% for each additional enchantment (max 80%). All nearby foes are struck for 10...40 earth damage each time a Dervish enchantment is removed from you.', 'Flash Enchantment Spell. (20 seconds.) 40% chance to block and an extra 4...10% for each additional enchantment. 10...40 earth damage to nearby foes when you lose a Dervish enchantment.', 'Mirage Cloak (PvP)', 'Flash Enchantment Spell. For 1...7 seconds, you have a 30...60% chance to block incoming attacks. When you cast this enchantment, all nearby foes are struck for 10...40 earth damage.', 'Flash Enchantment Spell. (1...7 seconds.) You have 30...60% chance to block. Initial Effect: deals 10...40 earth damage to nearby foes.'),
  (1502, 'Arcane Zeal', 'Elite Enchantment Spell. For 10 seconds, whenever you cast a spell, you gain 2 Energy for each enchantment on you (maximum 2...7 Energy).', 'Elite Enchantment Spell. (10 seconds.) You gain 2 Energy (maximum 2...7) for each enchantment on you whenever you cast a spell.', 'Arcane Zeal', 'Elite Enchantment Spell. For 10 seconds, whenever you cast a spell, you gain 2 Energy for each enchantment on you (maximum 2...7 Energy).', 'Elite Enchantment Spell. (10 seconds.) You gain 2 Energy (maximum 2...7) for each enchantment on you whenever you cast a spell.'),
  (1503, 'Mystic Vigor', 'Enchantment Spell. For 20 seconds, every time you successfully hit with an attack, you gain 3...15 Health for each enchantment on you (maximum 25 Health).', 'Enchantment Spell. (20 seconds.) You gain 3...15 Health (maximum 25) for each enchantment on you whenever you hit with an attack.', 'Mystic Vigor', 'Enchantment Spell. For 20 seconds, every time you successfully hit with an attack, you gain 3...15 Health for each enchantment on you (maximum 25 Health).', 'Enchantment Spell. (20 seconds.) You gain 3...15 Health (maximum 25) for each enchantment on you whenever you hit with an attack.'),
  (1504, 'Watchful Intervention', 'Enchantment Spell. For 60 seconds, the next time damage drops target ally''s Health below 25%, that ally is healed for 50...200 Health.', 'Enchantment Spell. (60 seconds.) Heals for 50...200 the next time damage drops target ally''s Health below 25%.', 'Watchful Intervention', 'Enchantment Spell. For 60 seconds, the next time damage drops target ally''s Health below 25%, that ally is healed for 50...200 Health.', 'Enchantment Spell. (60 seconds.) Heals for 50...200 the next time damage drops target ally''s Health below 25%.'),
  (1505, 'Vow of Piety', 'Enchantment Spell. For 20 seconds, you have +24 armor and +1...4 Health regeneration. Vow of Piety renews whenever an enchantment on you ends.', 'Enchantment Spell. (20 seconds.) +24 armor and +1...4 Health regeneration. Renewal: whenever an enchantment on you ends.', 'Vow of Piety', 'Enchantment Spell. For 20 seconds, you have +24 armor and +1...4 Health regeneration. Vow of Piety renews whenever an enchantment on you ends.', 'Enchantment Spell. (20 seconds.) +24 armor and +1...4 Health regeneration. Renewal: whenever an enchantment on you ends.'),
  (1506, 'Vital Boon', 'Enchantment Spell. For 20 seconds, you have +40...100 maximum Health. When this enchantment ends, you are healed for 75...200 Health.', 'Enchantment Spell. (20 seconds.) You have +40...100 maximum Health. End effect: heals you for 75...200.', 'Vital Boon', 'Enchantment Spell. For 20 seconds, you have +40...100 maximum Health. When this enchantment ends, you are healed for 75...200 Health.', 'Enchantment Spell. (20 seconds.) You have +40...100 maximum Health. End effect: heals you for 75...200.'),
  (1507, 'Heart of Holy Flame', 'Flash Enchantment Spell. All nearby foes take 5...30 holy damage. For 30 seconds afterward, your attacks deal holy damage. When this enchantment ends, all nearby foes are set on fire for 2...5 seconds.', 'Flash Enchantment Spell. (30 seconds.) Your attacks deal holy damage. Initial effect: deals 5...30 holy damage to nearby foes. End effect: inflicts Burning condition (2...5 seconds) on nearby foes.', 'Heart of Holy Flame', 'Flash Enchantment Spell. All nearby foes take 5...30 holy damage. For 30 seconds afterward, your attacks deal holy damage. When this enchantment ends, all nearby foes are set on fire for 2...5 seconds.', 'Flash Enchantment Spell. (30 seconds.) Your attacks deal holy damage. Initial effect: deals 5...30 holy damage to nearby foes. End effect: inflicts Burning condition (2...5 seconds) on nearby foes.'),
  (1508, 'Extend Enchantments', 'Skill. For 10 seconds, your next Dervish enchantment lasts 10...150% longer.', 'Skill. (10 seconds)Your next Dervish enchantment lasts 10...150% longer.', 'Extend Enchantments', 'Skill. For 10 seconds, your next Dervish enchantment lasts 10...150% longer.', 'Skill. (10 seconds)Your next Dervish enchantment lasts 10...150% longer.'),
  (1509, 'Faithful Intervention', 'Enchantment Spell. If damage drops your Health below 50%, Faithful Intervention ends. When Faithful Intervention ends, you are healed for 30...150 Health.', 'Enchantment Spell. You gain 30...150 Health the next time damage drops your Health below 50%.', 'Faithful Intervention', 'Enchantment Spell. If damage drops your Health below 50%, Faithful Intervention ends. When Faithful Intervention ends, you are healed for 30...150 Health.', 'Enchantment Spell. You gain 30...150 Health the next time damage drops your Health below 50%.'),
  (1510, 'Sand Shards', 'Flash Enchantment Spell. For 30 seconds, the next 1...5 times you hit with a scythe, all other adjacent foes take 10...60 earth damage.', 'Flash Enchantment Spell. (30 seconds.) Deals 10...60 earth damage to all other adjacent foes whenever you hit with your scythe. Ends after 1...5 hits.', 'Sand Shards', 'Flash Enchantment Spell. For 30 seconds, the next 1...5 times you hit with a scythe, all other adjacent foes take 10...60 earth damage.', 'Flash Enchantment Spell. (30 seconds.) Deals 10...60 earth damage to all other adjacent foes whenever you hit with your scythe. Ends after 1...5 hits.'),
  (1512, 'Lyssa''s Haste', 'Flash Enchantment Spell. For 3...15 seconds, your Dervish enchantments recharge 33% faster. When you activate this enchantment, all adjacent foes are interrupted. When this enchantment ends, all adjacent foes are interrupted. 50% failure chance unless Wind Prayers 5 or higher.', 'Flash Enchantment Spell. (3...15 seconds.) Your Dervish enchantments recharge 33% faster. Initial Effect: interrupts all adjacent foes. End Effect: interrupts all adjacent foes. (50% failure chance unless Wind Prayers 5 or higher.)', 'Lyssa''s Haste (PvP)', 'Flash Enchantment Spell. For 3...15 seconds, your Dervish enchantments recharge 33% faster. When you activate this enchantment, all adjacent foes are interrupted. When this enchantment ends, all adjacent foes are interrupted. 50% failure chance unless Wind Prayers 5 or higher.', 'Flash Enchantment Spell. (3...15 seconds.) Your Dervish enchantments recharge 33% faster. Initial Effect: interrupts all adjacent foes. End Effect: interrupts all adjacent foes. (50% failure chance unless Wind Prayers 5 or higher.)'),
  (1513, 'Guiding Hands', 'Enchantment Spell. For 20 seconds, your next 0...3 attacks cannot be blocked. When activated, this skill removes the Blindness condition.', 'Enchantment Spell. (20 seconds.) Your next 0...3 attacks cannot be blocked. Initial effect: removes Blindness.', 'Guiding Hands (PvP)', 'Enchantment Spell. For 20 seconds, your next 0...3 attacks cannot be blocked. When activated, this skill removes the Blindness condition.', 'Enchantment Spell. (20 seconds.) Your next 0...3 attacks cannot be blocked. Initial effect: removes Blindness.'),
  (1514, 'Fleeting Stability', 'Flash Enchantment Spell. For 4...10 seconds, you cannot be knocked down and move 25% faster. This enchantment ends prematurely if it prevents a knockdown.', 'Flash Enchantment Spell. (4...10 seconds.) You cannot be knocked down and move 25% faster. Ends if knockdown prevented.', 'Fleeting Stability (PvP)', 'Flash Enchantment Spell. For 2...8 seconds, you cannot be knocked down and move 25% faster. This enchantment ends prematurely if it prevents a knockdown.', 'Flash Enchantment Spell. (2...8 seconds.) You cannot be knocked down and move 25% faster. Ends if knockdown prevented.'),
  (1515, 'Armor of Sanctity', 'Enchantment Spell. All adjacent foes suffer from Weakness for 5...15 seconds. For 15 seconds, you take 5...20 less damage from foes suffering from a condition.', 'Enchantment Spell. Inflicts Weakness condition on all adjacent foes (5...15 seconds). You take 5...20 less damage from foes with a condition (15 seconds).', 'Armor of Sanctity', 'Enchantment Spell. All adjacent foes suffer from Weakness for 5...15 seconds. For 15 seconds, you take 5...20 less damage from foes suffering from a condition.', 'Enchantment Spell. Inflicts Weakness condition on all adjacent foes (5...15 seconds). You take 5...20 less damage from foes with a condition (15 seconds).'),
  (1516, 'Mystic Regeneration', 'Enchantment Spell. For 5...20 seconds, you have +1...4 Health regeneration for each enchantment (maximum of 8) on you.', 'Enchantment Spell. (5...20 seconds.) You have +1...4 Health regeneration for each enchantment (maximum of 8) on you.', 'Mystic Regeneration (PvP)', 'Enchantment Spell. For 5...20 seconds, you have +1...4 Health regeneration for each enchantment (maximum of 3) on you.', 'Enchantment Spell. (5...20 seconds.) You have +1...4 Health regeneration for each enchantment (maximum of 3) on you.'),
  (1517, 'Vow of Silence', 'Elite Enchantment Spell. For 5...10 seconds, you cannot be the target of spells, and you cannot cast spells.', 'Elite Enchantment Spell. (5...10 seconds.) Spells cannot target you. You cannot cast spells.', 'Vow of Silence', 'Elite Enchantment Spell. For 5...10 seconds, you cannot be the target of spells, and you cannot cast spells.', 'Elite Enchantment Spell. (5...10 seconds.) Spells cannot target you. You cannot cast spells.'),
  (1518, 'Avatar of Balthazar', 'Elite Form. For 10...90 seconds, you gain +20 armor against physical damage, you gain adrenaline 25% faster, your attacks deal holy damage, and whenever you lose a Dervish enchantment, nearby foes are set on fire for 1...3 seconds. This skill is disabled for 45 seconds.', 'Elite Form. (10...90 seconds.) You gain +20 armor against physical damage, you gain adrenaline 25% faster, your attacks deal holy damage, you inflict Burning (1...3 seconds) on nearby foes whenever you lose a Dervish enchantment. This skill is disabled for 45 seconds.', 'Avatar of Balthazar', 'Elite Form. For 10...90 seconds, you gain +20 armor against physical damage, you gain adrenaline 25% faster, your attacks deal holy damage, and whenever you lose a Dervish enchantment, nearby foes are set on fire for 1...3 seconds. This skill is disabled for 45 seconds.', 'Elite Form. (10...90 seconds.) You gain +20 armor against physical damage, you gain adrenaline 25% faster, your attacks deal holy damage, you inflict Burning (1...3 seconds) on nearby foes whenever you lose a Dervish enchantment. This skill is disabled for 45 seconds.'),
  (1519, 'Avatar of Dwayna', 'Elite Form. For 10...90 seconds, your attacks deal holy damage. Whenever you use a Dervish attack skill, you lose 1 hex. Whenever you lose a Dervish enchantment, all allies in earshot are healed for 5...50 Health. This skill is disabled for 45 seconds.', 'Elite Form. (10...90 seconds.) Deal holy damage. You lose 1 hex whenever you use a Dervish attack skill. Heal allies in earshot for 5...50 Health whenever you lose a Dervish enchantment. This skill is disabled for 45 seconds.', 'Avatar of Dwayna (PvP)', 'Elite Form. For 10...90 seconds, your attacks deal holy damage. Whenever you use a Dervish attack skill, you lose 1 hex. Whenever you lose a Dervish enchantment, you are healed for 5...50 Health. This skill is disabled for 45 seconds.', 'Elite Form. (10...90 seconds.) Deal holy damage. You lose 1 hex whenever you use a Dervish attack skill. Heal yourself for 5...50 Health whenever you lose a Dervish enchantment. This skill is disabled for 45 seconds.'),
  (1520, 'Avatar of Grenth', 'Elite Form. For 10...90 seconds, your scythe attacks deal dark damage and steal 0...12 Health. You are immune to Disease and inflict Disease on all adjacent foes for 3 seconds whenever you lose a Dervish enchantment. This skill is disabled for 45 seconds.', 'Elite Form. (10...90 seconds.) Your scythe attacks deal dark damage and steal 0...12 Health. You are immune to Disease. Apply Disease to all adjacent foes (3 seconds) when you lose a Dervish enchantment. This skill is disabled for 45 seconds.', 'Avatar of Grenth', 'Elite Form. For 10...90 seconds, your scythe attacks deal dark damage and steal 0...12 Health. You are immune to Disease and inflict Disease on all adjacent foes for 3 seconds whenever you lose a Dervish enchantment. This skill is disabled for 45 seconds.', 'Elite Form. (10...90 seconds.) Your scythe attacks deal dark damage and steal 0...12 Health. You are immune to Disease. Apply Disease to all adjacent foes (3 seconds) when you lose a Dervish enchantment. This skill is disabled for 45 seconds.'),
  (1521, 'Avatar of Lyssa', 'Elite Form. For 10...90 seconds, your Dervish enchantments recharge 50% faster and your attacks deal chaos damage. Whenever you lose a Dervish enchantment, steal 1 Energy from all nearby foes. This skill is disabled for 45 seconds.', 'Elite Form. (10...90 seconds.) Your Dervish enchantments recharge 50% faster and deal chaos damage with attacks. Steal 1 Energy from nearby foes when you lose a Dervish enchantment. This skill is disabled for 45 seconds.', 'Avatar of Lyssa', 'Elite Form. For 10...90 seconds, your Dervish enchantments recharge 50% faster and your attacks deal chaos damage. Whenever you lose a Dervish enchantment, steal 1 Energy from all nearby foes. This skill is disabled for 45 seconds.', 'Elite Form. (10...90 seconds.) Your Dervish enchantments recharge 50% faster and deal chaos damage with attacks. Steal 1 Energy from nearby foes when you lose a Dervish enchantment. This skill is disabled for 45 seconds.'),
  (1522, 'Avatar of Melandru', 'Elite Form. For 10...90 seconds, you have +150 Health, +30 elemental armor, and your attacks deal earth damage. Whenever you lose a Dervish enchantment, all party members in earshot lose 1 condition. This skill is disabled for 45 seconds.', 'Elite Form. (10...90 seconds.) You have +150 maximum Health, +30 elemental armor, and your attacks deal earth damage. Cure 1 condition from all party members in earshot whenever you lose a Dervish enchantment. This skill is disabled for 45 seconds.', 'Avatar of Melandru (PvP)', 'Elite Form. For 10...90 seconds, you have +100 Health, +30 elemental armor, and your attacks deal earth damage. Whenever you lose a Dervish enchantment you lose 2 conditions. This skill is disabled for 45 seconds.', 'Elite Form. (10...90 seconds.) You have +100 maximum Health, +30 elemental armor, and your attacks deal earth damage. Cure 2 conditions from yourself whenever you lose a Dervish enchantment. This skill is disabled for 45 seconds.'),
  (1523, 'Meditation', 'Enchantment Spell. Lose all adrenaline. For 20 seconds, you gain 1...4 Energy every time an enchantment on you ends.', 'Enchantment Spell. (20 seconds.) Lose all adrenaline. Gain 1...4 Energy whenever an enchantment on you ends.', 'Meditation', 'Enchantment Spell. Lose all adrenaline. For 20 seconds, you gain 1...4 Energy every time an enchantment on you ends.', 'Enchantment Spell. (20 seconds.) Lose all adrenaline. Gain 1...4 Energy whenever an enchantment on you ends.'),
  (1524, 'Eremite''s Zeal', 'Enchantment Spell. You gain 1...3 Energy for each foe within earshot, maximum 8 Energy. For 10 seconds afterward, this enchantment does nothing. When this enchantment ends, you gain 1...3 Energy for each foe within earshot, maximum 8 Energy.', 'Enchantment Spell. (10 seconds.) Initial effect: you gain 1...3 Energy (maximum 8) for each foe in earshot. End effect: you gain 1...3 Energy (maximum 8) for each foe in earshot.', 'Eremite''s Zeal', 'Enchantment Spell. You gain 1...3 Energy for each foe within earshot, maximum 8 Energy. For 10 seconds afterward, this enchantment does nothing. When this enchantment ends, you gain 1...3 Energy for each foe within earshot, maximum 8 Energy.', 'Enchantment Spell. (10 seconds.) Initial effect: you gain 1...3 Energy (maximum 8) for each foe in earshot. End effect: you gain 1...3 Energy (maximum 8) for each foe in earshot.'),
  (1525, 'Natural Healing', 'Spell. You are healed for 50...170 Health. If you are not enchanted, this spell activates 50% faster.', 'Spell. Heals you for 50...170 Health. This skill activates 50% faster if you are not enchanted.', 'Natural Healing', 'Spell. You are healed for 50...170 Health. If you are not enchanted, this spell activates 50% faster.', 'Spell. Heals you for 50...170 Health. This skill activates 50% faster if you are not enchanted.'),
  (1526, 'Imbue Health', 'Spell. Target other ally is healed for 5...50% of your current Health (maximum 300 Health).', 'Spell. Heals for 5...50% of your current Health (maximum 300). Cannot self-target.', 'Imbue Health', 'Spell. Target other ally is healed for 5...50% of your current Health (maximum 300 Health).', 'Spell. Heals for 5...50% of your current Health (maximum 300). Cannot self-target.'),
  (1527, 'Mystic Healing', 'Spell. You are healed for 5...65 Health. Also heals all enchanted party members for 5...65 Health.', 'Spell. Heals you for 5...65. Heals all enchanted party members for 5...65 Health.', 'Mystic Healing (PvP)', 'Spell. You are healed for 5...65 Health. Also heals all enchanted party members for 5...65 Health.', 'Spell. Heals you for 5...65. Heals all enchanted party members for 5...65 Health.'),
  (1528, 'Dwayna''s Touch', 'Spell. Target touched ally is healed for 60 Health for each enchantment on you (maximum 60...240).', 'Touch Spell. Heals for 60 (maximum 60...240) for each enchantment on you.', 'Dwayna''s Touch', 'Spell. Target touched ally is healed for 60 Health for each enchantment on you (maximum 60...240).', 'Touch Spell. Heals for 60 (maximum 60...240) for each enchantment on you.'),
  (1529, 'Pious Restoration', 'Spell. You gain 80...150 Health and remove 1 Dervish enchantment. If an enchantment was removed in this way, you also lose 1...3 hexes.', 'Spell. Gain 80...150 Health and remove 1 Dervish enchantment. Removal effect: lose 1...3 hexes.', 'Pious Restoration (PvP)', 'Spell. You gain 80...150 Health and remove 1 Dervish enchantment. If an enchantment was removed in this way, you also lose 1 hexes.', 'Spell. Gain 80...150 Health and remove 1 Dervish enchantment. Removal effect: lose 1 hexes.'),
  (1530, 'Signet of Pious Light', 'Signet. Remove 1 Dervish enchantment. Target ally is healed for 30...150 Health. If an enchantment was removed in this way, this signet recharges 75% faster.', 'Signet. Heals for 30...150 Health. Removes 1 of your Dervish enchantments. Removal effect: recharges 75% faster.', 'Signet of Pious Light', 'Signet. Remove 1 Dervish enchantment. Target ally is healed for 30...150 Health. If an enchantment was removed in this way, this signet recharges 75% faster.', 'Signet. Heals for 30...150 Health. Removes 1 of your Dervish enchantments. Removal effect: recharges 75% faster.'),
  (1531, 'Intimidating Aura', 'Enchantment Spell. For 60 seconds, you have +40...100 max Health and take 1...10 less damage from foes with less Health than you.', 'Enchantment Spell. (60 seconds.) You have +40...100 max Health and take -1...10 damage from foes with less Health than you.', 'Intimidating Aura', 'Enchantment Spell. For 60 seconds, you have +40...100 max Health and take 1...10 less damage from foes with less Health than you.', 'Enchantment Spell. (60 seconds.) You have +40...100 max Health and take -1...10 damage from foes with less Health than you.'),
  (1532, 'Mystic Sandstorm', 'Spell. Create a Sandstorm at your location that lasts 3 seconds. Each second, foes nearby this location take 10...40 earth damage. Attacking foes take an additional 10...20 damage. If you are enchanted when you cast this spell, it lasts twice as long.', 'Spell. (3 seconds). Deals 10...40 earth damage each second. Deals an additional 10...20 damage to attacking foes. Hits foes nearby your initial location. Lasts twice as long if you are enchanted.', 'Mystic Sandstorm', 'Spell. Create a Sandstorm at your location that lasts 3 seconds. Each second, foes nearby this location take 10...40 earth damage. Attacking foes take an additional 10...20 damage. If you are enchanted when you cast this spell, it lasts twice as long.', 'Spell. (3 seconds). Deals 10...40 earth damage each second. Deals an additional 10...20 damage to attacking foes. Hits foes nearby your initial location. Lasts twice as long if you are enchanted.'),
  (1533, 'Winds of Disenchantment', 'Spell. Remove 1 of your Dervish enchantments. If an enchantment was removed, all nearby foes lose 1 enchantment and take 20...80 cold damage.', 'Spell. Remove 1 of your Dervish enchantments. Removal effect: all nearby foes lose 1 enchantment and take 20...80 cold damage.', 'Winds of Disenchantment', 'Spell. Remove 1 of your Dervish enchantments. If an enchantment was removed, all nearby foes lose 1 enchantment and take 20...80 cold damage.', 'Spell. Remove 1 of your Dervish enchantments. Removal effect: all nearby foes lose 1 enchantment and take 20...80 cold damage.'),
  (1534, 'Rending Touch', 'Spell. Deals 15...65 cold damage to target foe. You lose 1 Dervish enchantment. If an enchantment was removed, target foe loses 1 enchantment and you gain 2 strikes of adrenaline.', 'Touch Spell. Deals 15...65 cold damage. Lose 1 Dervish enchantment. Removal effect: target foe loses 1 enchantment and you gain 2 strikes of adrenaline.', 'Rending Touch', 'Spell. Deals 15...65 cold damage to target foe. You lose 1 Dervish enchantment. If an enchantment was removed, target foe loses 1 enchantment and you gain 2 strikes of adrenaline.', 'Touch Spell. Deals 15...65 cold damage. Lose 1 Dervish enchantment. Removal effect: target foe loses 1 enchantment and you gain 2 strikes of adrenaline.'),
  (1535, 'Crippling Sweep', 'Scythe Attack. If this attack hits a foe, that foe is Crippled for 3...12 seconds. This skill deals +3...15 extra damage if that foe is moving.', 'Scythe Attack. (3...12 seconds.) Inflicts Cripple condition. Deals +3...15 damage to moving foes.', 'Crippling Sweep', 'Scythe Attack. If this attack hits a foe, that foe is Crippled for 3...12 seconds. This skill deals +3...15 extra damage if that foe is moving.', 'Scythe Attack. (3...12 seconds.) Inflicts Cripple condition. Deals +3...15 damage to moving foes.'),
  (1536, 'Wounding Strike', 'Elite Scythe Attack. If this attack hits, you do +5...20 damage, target foe suffers from Bleeding for 5...20 seconds, and you lose 1 Dervish enchantment. If an enchantment was removed, target foe also suffers from a Deep Wound for 5...20 seconds.', 'Elite Scythe Attack. Deals +5...20 damage and inflicts Bleeding condition (5...20 seconds). Remove 1 Dervish enchantment. Removal Effect: inflicts Deep Wound condition (5...20 seconds).', 'Wounding Strike (PvP)', 'Elite Scythe Attack. If this attack hits, target foe suffers from Bleeding for 5...20 seconds, and you lose 1 Dervish enchantment. If an enchantment was removed, target foe also suffers from a Deep Wound for 5...20 seconds.', 'Elite Scythe Attack. Inflicts Bleeding condition (5...20 seconds). Removes 1 Dervish enchantment. Removal effect: inflicts Deep Wound condition (5...20 seconds).'),
  (1537, 'Wearying Strike', 'Scythe Attack. You remove 1 Dervish enchantment. If an enchantment was removed, you inflict a Deep Wound for 3...10 seconds. You suffer from Weakness for 10 seconds if an enchantment is not removed.', 'Scythe Attack. Remove 1 Dervish Enchantment. Removal Effect: Inflicts Deep Wound condition (3...10 seconds). You are Weakened (10 seconds) if an enchantment is not lost.', 'Wearying Strike', 'Scythe Attack. You remove 1 Dervish enchantment. If an enchantment was removed, you inflict a Deep Wound for 3...10 seconds. You suffer from Weakness for 10 seconds if an enchantment is not removed.', 'Scythe Attack. Remove 1 Dervish Enchantment. Removal Effect: Inflicts Deep Wound condition (3...10 seconds). You are Weakened (10 seconds) if an enchantment is not lost.'),
  (1538, 'Lyssa''s Assault', 'Scythe Attack. This attack interrupts an action if it hits. If you are enchanted, any skill you interrupt is disabled for an additional 1...10 seconds. This attack does 50% of normal damage.', 'Scythe Attack. Interrupts an action. If you are enchanted, the interrupted skill is disabled for an additional 1...10 seconds. This attack does 50% of normal damage.', 'Lyssa''s Assault', 'Scythe Attack. This attack interrupts an action if it hits. If you are enchanted, any skill you interrupt is disabled for an additional 1...10 seconds. This attack does 50% of normal damage.', 'Scythe Attack. Interrupts an action. If you are enchanted, the interrupted skill is disabled for an additional 1...10 seconds. This attack does 50% of normal damage.'),
  (1539, 'Chilling Victory', 'Scythe Attack. If it hits, this attack strikes for +3...15 damage. For each foe hit who has less Health than you, that foe and all adjacent foes are struck for 10...30 cold damage.', 'Scythe Attack. Deals +3...15 damage. Deals 10...30 cold damage to each foe hit who has less Health than you and foes adjacent to those targets.', 'Chilling Victory', 'Scythe Attack. If it hits, this attack strikes for +3...15 damage. For each foe hit who has less Health than you, that foe and all adjacent foes are struck for 10...30 cold damage.', 'Scythe Attack. Deals +3...15 damage. Deals 10...30 cold damage to each foe hit who has less Health than you and foes adjacent to those targets.'),
  (1540, 'Conviction', 'Flash Enchantment Spell. For 10 seconds, you gain +10 armor if you have a condition and gain 1...3 Health regen for each condition you are suffering from. When this enchantment ends, you are cured of 1...2 conditions.', 'Flash Enchantment Spell. (10 seconds.) Gain +10 armor while conditioned. Gain 1...3 Health regeneration for each condition you have. End Effect: remove 1...2 conditions.', 'Conviction', 'Flash Enchantment Spell. For 10 seconds, you gain +10 armor if you have a condition and gain 1...3 Health regen for each condition you are suffering from. When this enchantment ends, you are cured of 1...2 conditions.', 'Flash Enchantment Spell. (10 seconds.) Gain +10 armor while conditioned. Gain 1...3 Health regeneration for each condition you have. End Effect: remove 1...2 conditions.'),
  (1541, 'Enchanted Haste', 'Flash Enchantment Spell. For 7 seconds, you move 25% faster. If this enchantment ends prematurely, you lose 1 conditions.', 'Flash Enchantment Spell. (7 seconds.) You move 25% faster. Lose 1 conditions if this enchantment ends prematurely.', 'Enchanted Haste', 'Flash Enchantment Spell. For 7 seconds, you move 25% faster. If this enchantment ends prematurely, you lose 1 conditions.', 'Flash Enchantment Spell. (7 seconds.) You move 25% faster. Lose 1 conditions if this enchantment ends prematurely.'),
  (1542, 'Pious Concentration', 'Stance. For 5...20 seconds, you cannot be interrupted, but each time you would have been interrupted, you lose 1 Dervish enchantment or Pious Concentration ends.', 'Stance. (5...20 seconds.) Prevents interrupts. Prevention cost: you lose one Dervish enchantment or Pious Concentration ends.', 'Pious Concentration', 'Stance. For 5...20 seconds, you cannot be interrupted, but each time you would have been interrupted, you lose 1 Dervish enchantment or Pious Concentration ends.', 'Stance. (5...20 seconds.) Prevents interrupts. Prevention cost: you lose one Dervish enchantment or Pious Concentration ends.'),
  (1543, 'Pious Haste', 'Stance. You remove 1 Dervish enchantment and for 1...7 seconds you move 25% faster. If an enchantment was removed you run 50% faster instead.', 'Stance. (1...7 seconds.) Lose 1 Dervish enchantment and move 25% faster. Removal Effect: Run 50% faster instead.', 'Pious Haste', 'Stance. You remove 1 Dervish enchantment and for 1...7 seconds you move 25% faster. If an enchantment was removed you run 50% faster instead.', 'Stance. (1...7 seconds.) Lose 1 Dervish enchantment and move 25% faster. Removal Effect: Run 50% faster instead.'),
  (1544, 'Whirling Charge', 'Flash Enchantment Spell. For 1...6 seconds, you move 33% faster than normal. The next time you strike a foe, all other nearby foes take 10...60 cold damage and this enchantment ends.', 'Flash Enchantment Spell. (1...6 seconds.) You move 33% faster. Deal 10...60 cold damage to all other nearby foes the next time you hit a foe and this enchantment ends.', 'Whirling Charge (PvP)', 'Flash Enchantment Spell. For 1...6 seconds, you move 33% faster than normal. The next time you strike a foe, all other nearby foes take 10...50 cold damage and this enchantment ends.', 'Flash Enchantment Spell. (1...6 seconds.) You move 33% faster. Deal 10...50 cold damage to all other nearby foes the next time you hit a foe and this enchantment ends.'),
  (1545, 'Test of Faith', 'Spell. Deals 15...75 cold damage and takes 1 enchantment from target foe. If that foe was not enchanted, that foe is Dazed for 2...6 seconds.', 'Touch Spell. Deals 15...75 cold damage and removes 1 enchantment. Target foe is Dazed for 2...6 seconds if that foe was not enchanted.', 'Test of Faith', 'Spell. Deals 15...75 cold damage and takes 1 enchantment from target foe. If that foe was not enchanted, that foe is Dazed for 2...6 seconds.', 'Touch Spell. Deals 15...75 cold damage and removes 1 enchantment. Target foe is Dazed for 2...6 seconds if that foe was not enchanted.'),
  (1546, 'Blazing Spear', 'Spear Attack. If this attack hits, it deals +5...25 damage and sets target foe on Fire for 1...3 seconds.', 'Spear Attack. Deals +5...25 damage. Inflicts Burning condition (1...3 seconds).', 'Blazing Spear', 'Spear Attack. If this attack hits, it deals +5...25 damage and sets target foe on Fire for 1...3 seconds.', 'Spear Attack. Deals +5...25 damage. Inflicts Burning condition (1...3 seconds).'),
  (1547, 'Mighty Throw', 'Spear Attack. Your spear moves three times faster. If it hits, you deal +10...40 damage.', 'Spear Attack. Deals +10...40 damage. This spear moves three times faster.', 'Mighty Throw (PvP)', 'Spear Attack. Your spear moves three times faster. If it hits, you deal +10...40 damage.', 'Spear Attack. Deals +10...40 damage. This spear moves three times faster.'),
  (1548, 'Cruel Spear', 'Elite Spear Attack. If this attack hits, you deal +10...50 damage. If it hits a non-moving target, you inflict a Deep Wound for 5...20 seconds.', 'Elite Spear Attack. Deals +10...50 damage. Inflicts Deep Wound condition (5...20 seconds) if target is not moving.', 'Cruel Spear', 'Elite Spear Attack. If this attack hits, you deal +10...50 damage. If it hits a non-moving target, you inflict a Deep Wound for 5...20 seconds.', 'Elite Spear Attack. Deals +10...50 damage. Inflicts Deep Wound condition (5...20 seconds) if target is not moving.'),
