  (1584, 'Leader''s Comfort', 'Skill. You gain 30...75 Health. For each ally within earshot, you also gain +10...20 Health (maximum 140 Health).', 'Skill. You gain 30...75 Health. You also gain 10...20 Health (maximum 140) for each ally in earshot.', 'Leader''s Comfort', 'Skill. You gain 30...75 Health. For each ally within earshot, you also gain +10...20 Health (maximum 140 Health).', 'Skill. You gain 30...75 Health. You also gain 10...20 Health (maximum 140) for each ally in earshot.'),
  (1585, 'Signet of Synergy', 'Signet. Target other ally is healed for 40...100 Health. If you are not under the effects of an enchantment, you are also healed for 40...100 Health.', 'Signet. Heal target ally for 40...100. You are also healed for 40...100 if you are not enchanted. Cannot self-target.', 'Signet of Synergy', 'Signet. Target other ally is healed for 40...100 Health. If you are not under the effects of an enchantment, you are also healed for 40...100 Health.', 'Signet. Heal target ally for 40...100. You are also healed for 40...100 if you are not enchanted. Cannot self-target.'),
  (1586, 'Angelic Protection', 'Skill. For 10 seconds, any time target other ally takes more than 250...80 damage per second, that ally is healed for any damage over that amount.', 'Skill. (10 seconds.) Each second that target ally takes damage over 250...80, that ally is healed for any damage over that amount. Cannot self target.', 'Angelic Protection', 'Skill. For 10 seconds, any time target other ally takes more than 250...80 damage per second, that ally is healed for any damage over that amount.', 'Skill. (10 seconds.) Each second that target ally takes damage over 250...80, that ally is healed for any damage over that amount. Cannot self target.'),
  (1587, 'Angelic Bond', 'Elite Skill. For 10 seconds, the next time an ally within earshot would take fatal damage, that damage is negated and that ally is healed for 20...200 Health. Angelic Bond ends on all other allies.', 'Elite Skill. (10 seconds.) The next time an ally within earshot would take fatal damage, that damage is negated and that ally is healed for 20...200. Ends on all other allies.', 'Angelic Bond', 'Elite Skill. For 10 seconds, the next time an ally within earshot would take fatal damage, that damage is negated and that ally is healed for 20...200 Health. Angelic Bond ends on all other allies.', 'Elite Skill. (10 seconds.) The next time an ally within earshot would take fatal damage, that damage is negated and that ally is healed for 20...200. Ends on all other allies.'),
  (1588, 'Cautery Signet', 'Elite Signet. All party members lose all conditions. You are set on Fire for 1 second for each condition removed in this way.', 'Elite Signet. All party members lose all conditions. You begin Burning (one second for each condition removed).', 'Cautery Signet', 'Elite Signet. All party members lose all conditions. You are set on Fire for 1 second for each condition removed in this way.', 'Elite Signet. All party members lose all conditions. You begin Burning (one second for each condition removed).'),
  (1589, '"Stand Your Ground!"', 'Shout. For 5...20 seconds, all party members within earshot receive +24 armor when not moving.', 'Shout. (5...20 seconds.) Party members in earshot gain +24 armor when not moving.', '"Stand Your Ground!" (PvP)', 'Shout. For 5...20 seconds, all party members within earshot receive +24 armor when not moving. This effect ends on an ally affected by this shout when that ally attacks.', 'Shout. (5...20 seconds.) Party members in earshot gain +24 armor when not moving. Ends for an ally if that ally attacks.'),
  (1590, '"Lead the Way!"', 'Shout. Target ally moves 25% faster for 1...5 seconds for each ally within earshot (maximum of 30 seconds).', 'Shout. Target ally moves 25% faster for 1...5 seconds (maximum of 30 seconds) for each ally in earshot.', '"Lead the Way!"', 'Shout. Target ally moves 25% faster for 1...5 seconds for each ally within earshot (maximum of 30 seconds).', 'Shout. Target ally moves 25% faster for 1...5 seconds (maximum of 30 seconds) for each ally in earshot.'),
  (1591, '"Make Haste!"', 'Shout. For 5...20 seconds, target other ally moves 33% faster. This skill ends if that ally successfully hits with an attack.', 'Shout. (5...20 seconds.) Target ally moves 33% faster. Ends if target ally hits with an attack. Cannot self-target.', '"Make Haste!"', 'Shout. For 5...20 seconds, target other ally moves 33% faster. This skill ends if that ally successfully hits with an attack.', 'Shout. (5...20 seconds.) Target ally moves 33% faster. Ends if target ally hits with an attack. Cannot self-target.'),
  (1592, '"We Shall Return!"', 'Shout. All party members in earshot are resurrected with 25...50% Health and 5...20% Energy.', 'Shout. All party members in earshot are resurrected (25...50% Health and 5...20% Energy).', '"We Shall Return!" (PvP)', 'Shout. For 10 seconds, whenever party members within earshot use a resurrection skill, their fallen allies return with 10...75% more Health and 5...50% more Energy.', 'Shout. (10 seconds.) Whenever party members in earshot use a resurrection skill, their fallen allies return with 10...75% more Health and 5...50% more Energy.'),
  (1593, '"Never Give Up!"', 'Shout. All allies within earshot and below 75% Health gain 1...10 Energy.', 'Shout. Allies in earshot gain 1...10 Energy. Only affects allies below 75% Health.', '"Never Give Up!"  (PvP)', 'Shout. All allies within earshot and below 75% Health gain 1...10 Energy.', 'Shout. Allies in earshot gain 1...10 Energy. Only affects allies below 75% Health.'),
  (1594, '"Help!"', 'Shout. Target non-spirit ally gains 15...90 Health. For 1...10 seconds, other allies'' spells targeting that ally cast 50% faster.', 'Shout. (1...10 seconds.) Target non-spirit ally gains 15...90 health, allied spells targeting them cast 50% faster.', '"Help!" (PvP)', 'Shout. Target non-spirit ally gains 5...50 Health. For 1...10 seconds, other allies'' spells targeting that ally cast 50% faster.', 'Shout. (1...10 seconds.) Target non-spirit ally gains 5...50 health, allied spells targeting them cast 50% faster.'),
  (1595, '"Fall Back!"', 'Shout. For 4...10 seconds, all allies within earshot gain 5...15 Health per second while moving and move 33% faster. "Fall Back!" ends on an ally affected by this shout when that ally successfully hits with an attack.', 'Shout. (4...10 seconds.) Allies in earshot gain 5...15 Health per second while moving and move 33% faster. Ends for an ally if that ally hits with an attack.', '"Fall Back!" (PvP)', 'Shout. For 4...10 seconds, all allies within earshot gain 5...15 Health per second while moving and move 33% faster. "Fall Back!" ends on an ally affected by this shout when that ally successfully hits with an attack.', 'Shout. (4...10 seconds.) Allies in earshot gain 5...15 Health per second while moving and move 33% faster. Ends for an ally if that ally hits with an attack.'),
  (1596, '"Incoming!"', 'Elite Shout. For 4...10 seconds, all allies within earshot move 33% faster and gain 5...15 Health per second while moving.', 'Elite Shout. (4...10 seconds.) Allies in earshot move 33% faster and gain 5...15 Health per second while moving.', '"Incoming!" (PvP)', 'Elite Shout. For 4...10 seconds, all allies within earshot move 33% faster and gain 5...15 Health per second while moving.', 'Elite Shout. (4...10 seconds.) Allies in earshot move 33% faster and gain 5...15 Health per second while moving.'),
  (1597, '"They''re on Fire!"', 'Shout. For 10 seconds, party members within earshot take 5...35% less damage from foes suffering from Burning.', 'Shout. (10 seconds.) Party members in earshot take 5...35% less damage from Burning foes.', '"They''re on Fire!"', 'Shout. For 10 seconds, party members within earshot take 5...35% less damage from foes suffering from Burning.', 'Shout. (10 seconds.) Party members in earshot take 5...35% less damage from Burning foes.'),
  (1598, '"Never Surrender!"', 'Shout. For 15 seconds, all party members within earshot and below 75% Health gain +1...5 Health regeneration.', 'Shout. (15 seconds.) Party members in earshot gain +1...5 Health regeneration. Only affects party members below 75% Health.', '"Never Surrender!" (PvP)', 'Shout. For 10 seconds, all party members within earshot and below 75% Health gain +1...5 Health regeneration.', 'Shout. (10 seconds.) Party members in earshot gain +1...5 Health regeneration. Only affects party members below 75% Health.'),
  (1599, '"It''s Just a Flesh Wound."', 'Elite Shout. Target other ally loses all conditions. If a condition was removed in this way, that ally moves 25% faster for 1...10 seconds.', 'Elite Shout. Remove all conditions from target ally. That ally moves 25% faster (1...10 seconds) if a condition was removed. Cannot self-target.', '"It''s Just a Flesh Wound."', 'Elite Shout. Target other ally loses all conditions. If a condition was removed in this way, that ally moves 25% faster for 1...10 seconds.', 'Elite Shout. Remove all conditions from target ally. That ally moves 25% faster (1...10 seconds) if a condition was removed. Cannot self-target.'),
