  (1602, 'Stunning Strike', 'Elite Spear Attack. If this attack hits, you deal +10...50 damage. If it hits a foe suffering from a condition, that foe is also Dazed for 4...10 seconds.', 'Elite Spear Attack. Deals +10...50 damage. Inflicts Dazed condition (4...10 seconds) if target has a condition.', 'Stunning Strike', 'Elite Spear Attack. If this attack hits, you deal +10...50 damage. If it hits a foe suffering from a condition, that foe is also Dazed for 4...10 seconds.', 'Elite Spear Attack. Deals +10...50 damage. Inflicts Dazed condition (4...10 seconds) if target has a condition.'),
  (1603, 'Merciless Spear', 'Spear Attack. If this attack hits a foe with less than 50% Health, that foe suffers from a Deep Wound for 5...20 seconds.', 'Spear Attack. Inflicts Deep Wound condition (5...20 seconds). No effect unless target has less than 50% Health.', 'Merciless Spear', 'Spear Attack. If this attack hits a foe with less than 50% Health, that foe suffers from a Deep Wound for 5...20 seconds.', 'Spear Attack. Inflicts Deep Wound condition (5...20 seconds). No effect unless target has less than 50% Health.'),
  (1604, 'Disrupting Throw', 'Spear Attack. If this attack hits a foe suffering from a condition, that foe is interrupted.', 'Spear Attack. Interrupts actions. No effect unless target has a condition.', 'Disrupting Throw', 'Spear Attack. If this attack hits a foe suffering from a condition, that foe is interrupted.', 'Spear Attack. Interrupts actions. No effect unless target has a condition.'),
