  (1643, 'Assault Enchantments', 'Elite Skill. Must follow a dual attack. Target foe loses all enchantments.', 'Elite Skill. Removes all enchantments. Must follow a dual attack.', 'Assault Enchantments', 'Elite Skill. Must follow a dual attack. Target foe loses all enchantments.', 'Elite Skill. Removes all enchantments. Must follow a dual attack.'),
  (1644, 'Wastrel''s Collapse', 'Elite Skill. Shadow Step to target foe. If target foe is not using a skill, that foe is knocked down. All of your non-dagger attack skills are disabled for 10 seconds.', 'Elite Skill. Shadow Step to target foe. Causes knock-down if target foe is not using a skill. Disables your non-dagger attack skills (10 seconds).', 'Wastrel''s Collapse', 'Elite Skill. Shadow Step to target foe. If target foe is not using a skill, that foe is knocked down. All of your non-dagger attack skills are disabled for 10 seconds.', 'Elite Skill. Shadow Step to target foe. Causes knock-down if target foe is not using a skill. Disables your non-dagger attack skills (10 seconds).'),
  (1645, 'Lift Enchantment', 'Skill. If target touched foe is knocked down, that foe loses one enchantment.', 'Touch Skill. Removes one enchantment.No effect unless target foe is knocked-down.', 'Lift Enchantment', 'Skill. If target touched foe is knocked down, that foe loses one enchantment.', 'Touch Skill. Removes one enchantment.No effect unless target foe is knocked-down.'),
