  (1653, 'Swap', 'Spell. You and target summoned creature Shadow Step to each other''s location.', 'Spell. You and target summoned creature Shadow Step to each other''s locations.', 'Swap', 'Spell. You and target summoned creature Shadow Step to each other''s location.', 'Spell. You and target summoned creature Shadow Step to each other''s locations.'),
  (1654, 'Shadow Meld', 'Elite Enchantment Spell. Shadow Step to target other ally. When you stop maintaining this enchantment, you return to your original location.', 'Elite Enchantment Spell. Shadow Step to target ally. End effect: return to your original location. Cannot self-target.', 'Shadow Meld', 'Elite Enchantment Spell. Shadow Step to target other ally. When you stop maintaining this enchantment, you return to your original location.', 'Elite Enchantment Spell. Shadow Step to target ally. End effect: return to your original location. Cannot self-target.'),
  (1655, 'Price of Pride', 'Hex Spell. For 5 seconds, the next time target foe uses an elite skill, that foe loses 3...15 Energy.', 'Hex Spell. (5 seconds.) Causes 3...15 Energy loss the next time target foe uses an elite skill.', 'Price of Pride', 'Hex Spell. For 5 seconds, the next time target foe uses an elite skill, that foe loses 3...15 Energy.', 'Hex Spell. (5 seconds.) Causes 3...15 Energy loss the next time target foe uses an elite skill.'),
  (1656, 'Air of Disenchantment', 'Elite Hex Spell. Remove one enchantment from target foe and all nearby foes. For 5...20 seconds, enchantments expire 150...300% faster on those foes.', 'Elite Hex Spell. Also hexes foes near your target (5...20 seconds). Remove one enchantment from target and nearby foes. Enchantments expire 150...300% faster on those foes.', 'Air of Disenchantment', 'Elite Hex Spell. Remove one enchantment from target foe and all nearby foes. For 5...20 seconds, enchantments expire 150...300% faster on those foes.', 'Elite Hex Spell. Also hexes foes near your target (5...20 seconds). Remove one enchantment from target and nearby foes. Enchantments expire 150...300% faster on those foes.'),
