  (1702, 'Steelfang Slash', 'Sword Attack. If this attack hits, you deal +1...31 damage. If you hit a foe that is knocked down, you gain 1...5 adrenaline.', 'Sword Attack. Deals +1...31 damage. You gain 1...5 adrenaline if target foe is knocked-down.', 'Steelfang Slash', 'Sword Attack. If this attack hits, you deal +1...31 damage. If you hit a foe that is knocked down, you gain 1...5 adrenaline.', 'Sword Attack. Deals +1...31 damage. You gain 1...5 adrenaline if target foe is knocked-down.'),
  (1719, 'Screaming Shot', 'Bow Attack. If this attack hits, you deal +10...25 damage. If your target is within earshot, that foe begins Bleeding for 5...20 seconds.', 'Bow Attack. Deals +10...25 damage. Inflicts Bleeding condition (5...20 seconds) if target foe is within earshot.', 'Screaming Shot', 'Bow Attack. If this attack hits, you deal +10...25 damage. If your target is within earshot, that foe begins Bleeding for 5...20 seconds.', 'Bow Attack. Deals +10...25 damage. Inflicts Bleeding condition (5...20 seconds) if target foe is within earshot.'),
  (1720, 'Keen Arrow', 'Bow Attack. If this attack hits, you strike for +5...20 damage. If you land a critical hit, you deal an additional +5...25 damage.', 'Bow Attack. Deals +5...20 damage. Deals +5...25 more damage if you land a critical hit.', 'Keen Arrow (PvP)', 'Bow Attack. If this attack hits, you strike for +5...15 damage. If you land a critical hit, you deal an additional +5...30 damage.', 'Bow Attack. Deals +5...15 damage. Deals +5...30 more damage if you land a critical hit.'),
