  (1784, 'Swift Javelin', 'Spear Attack. If this attack hits, you deal +5...20 damage. If you are under the effects of an enchantment, this spear flies twice as fast and cannot be blocked.', 'Spear Attack. Deals +5...20 damage. This spear moves twice as fast and is unblockable if you are enchanted.', 'Swift Javelin', 'Spear Attack. If this attack hits, you deal +5...20 damage. If you are under the effects of an enchantment, this spear flies twice as fast and cannot be blocked.', 'Spear Attack. Deals +5...20 damage. This spear moves twice as fast and is unblockable if you are enchanted.'),
  (1814, 'Lightbringer''s Gaze', 'Skill. Target demonic servant of Abaddon takes 100 holy damage and is interrupted. This skill strikes one additional foe in the area for each rank of Lightbringer you have attained. This skill is disabled for 15 seconds after it is used.', 'Skill. Target demonic servant of Abaddon takes 100 holy damage and is interrupted. Hits one additional foe in the area for each rank of Lightbringer you have attained. This skill is disabled (15 seconds).', 'Lightbringer''s Gaze', 'Skill. Target demonic servant of Abaddon takes 100 holy damage and is interrupted. This skill strikes one additional foe in the area for each rank of Lightbringer you have attained. This skill is disabled for 15 seconds after it is used.', 'Skill. Target demonic servant of Abaddon takes 100 holy damage and is interrupted. Hits one additional foe in the area for each rank of Lightbringer you have attained. This skill is disabled (15 seconds).'),
