  (1816, 'Sunspear Rebirth Signet', 'Signet. Resurrect target dead party member at your location with full Health and 10% Energy for each Sunspear rank you have attained. This signet can only be used once per mission unless recharged by a morale boost.', 'Signet. Resurrect target dead party member at your location (full Health and 10% Energy for each Sunspear rank you have attained). This signet only recharges when you gain a morale boost.', 'Sunspear Rebirth Signet', 'Signet. Resurrect target dead party member at your location with full Health and 10% Energy for each Sunspear rank you have attained. This signet can only be used once per mission unless recharged by a morale boost.', 'Signet. Resurrect target dead party member at your location (full Health and 10% Energy for each Sunspear rank you have attained). This signet only recharges when you gain a morale boost.'),
  (1948, 'Shadow Sanctuary', 'Enchantment Spell. You are Blinded for 5 seconds. For 10 seconds, you gain +7...10 Health regeneration and +40 armor.', 'Enchantment Spell. (10 seconds.) You gain +7...10 Health regeneration and +40 armor. You are Blind (5 seconds).', 'Shadow Sanctuary', 'Enchantment Spell. You are Blinded for 5 seconds. For 10 seconds, you gain +7...10 Health regeneration and +40 armor.', 'Enchantment Spell. (10 seconds.) You gain +7...10 Health regeneration and +40 armor. You are Blind (5 seconds).'),
  (1949, 'Ether Nightmare', 'Hex Spell. Target foe loses 5...8 Energy. For each point of Energy lost in this way, that foe and all foes in the area suffer -1 Health degeneration for 10 seconds.', 'Hex Spell. Causes 5...8 Energy loss. Target and foes in the area have -1 Health degeneration for each point of Energy lost (10 seconds).', 'Ether Nightmare', 'Hex Spell. Target foe loses 5...8 Energy. For each point of Energy lost in this way, that foe and all foes in the area suffer -1 Health degeneration for 10 seconds.', 'Hex Spell. Causes 5...8 Energy loss. Target and foes in the area have -1 Health degeneration for each point of Energy lost (10 seconds).'),
  (1950, 'Signet of Corruption', 'Signet. Target foe and all nearby foes take 20...30 damage. For each affected foe suffering from a condition or hex, you gain 2 Energy (maximum 12...20 Energy).', 'Signet. Deals 20...30 damage to target and nearby foes. You gain 2 Energy (maximum 12...20) for each of these foes with a condition or hex.', 'Signet of Corruption', 'Signet. Target foe and all nearby foes take 20...30 damage. For each affected foe suffering from a condition or hex, you gain 2 Energy (maximum 12...20 Energy).', 'Signet. Deals 20...30 damage to target and nearby foes. You gain 2 Energy (maximum 12...20) for each of these foes with a condition or hex.'),
  (1951, 'Elemental Lord', 'Enchantment Spell. For 40...60 seconds, your elemental attributes are boosted by 1. Each time you cast a spell, you gain 1 Energy for every 10 ranks of Energy Storage and are healed for 100...300% of the spell''s Energy cost.', 'Enchantment Spell. (40...60 seconds.) Your elemental attributes are boosted by 1. Each time you cast a spell, you gain 1 Energy for every 10 ranks of Energy Storage and are healed for 100...300% of the spell''s Energy cost.', 'Elemental Lord', 'Enchantment Spell. For 40...60 seconds, your elemental attributes are boosted by 1. Each time you cast a spell, you gain 1 Energy for every 10 ranks of Energy Storage and are healed for 100...300% of the spell''s Energy cost.', 'Enchantment Spell. (40...60 seconds.) Your elemental attributes are boosted by 1. Each time you cast a spell, you gain 1 Energy for every 10 ranks of Energy Storage and are healed for 100...300% of the spell''s Energy cost.'),
  (1952, 'Selfless Spirit', 'Enchantment Spell. For 15...20 seconds, spells you cast that target another ally cost 3 less Energy.', 'Enchantment Spell. (15...20 seconds.) Spells you cast that target another ally cost 3 less Energy.', 'Selfless Spirit', 'Enchantment Spell. For 15...20 seconds, spells you cast that target another ally cost 3 less Energy.', 'Enchantment Spell. (15...20 seconds.) Spells you cast that target another ally cost 3 less Energy.'),
  (1953, 'Triple Shot', 'Bow Attack. Shoot 3 arrows simultaneously at target foe. These arrows deal 40...25% less damage.', 'Bow Attack. Shoot 3 arrows simultaneously at target foe. These arrows deal 40...25% less damage.', 'Triple Shot', 'Bow Attack. Shoot 3 arrows simultaneously at target foe. These arrows deal 40...25% less damage.', 'Bow Attack. Shoot 3 arrows simultaneously at target foe. These arrows deal 40...25% less damage.'),
  (1954, '"Save Yourselves!"', 'Shout. For 4...6 seconds, all other party members gain +100 armor.', 'Shout. (4...6 seconds.) All other party members gain +100 armor.', '"Save Yourselves!"', 'Shout. For 4...6 seconds, all other party members gain +100 armor.', 'Shout. (4...6 seconds.) All other party members gain +100 armor.'),
