  (2197, 'Body Blow', 'Melee Attack. If this attack hits, target foe takes +10...40 damage. If target foe has Cracked Armor, that foe suffers from a Deep Wound for 0...15 seconds.', 'Melee Attack. Deals +10...40 damage. Inflicts Deep Wound (0...15 seconds) if target foe has Cracked Armor.', 'Body Blow', 'Melee Attack. If this attack hits, target foe takes +10...40 damage. If target foe has Cracked Armor, that foe suffers from a Deep Wound for 0...15 seconds.', 'Melee Attack. Deals +10...40 damage. Inflicts Deep Wound (0...15 seconds) if target foe has Cracked Armor.'),
  (2198, 'Body Shot', 'Bow Attack. If this attack hits, you deal +5...20 damage. If it hits a foe with Cracked Armor, you gain 5...10 Energy.', 'Bow Attack. Deals +5...20 damage. You gain 5...10 Energy if target foe has Cracked Armor.', 'Body Shot', 'Bow Attack. If this attack hits, you deal +5...20 damage. If it hits a foe with Cracked Armor, you gain 5...10 Energy.', 'Bow Attack. Deals +5...20 damage. You gain 5...10 Energy if target foe has Cracked Armor.'),
