  (2231, 'Ebon Battle Standard of Courage', 'Ward Spell. You plant an Ebon Battle Standard of Courage at your current location. For 14...20 seconds, non-spirit allies in this area gain +24 armor and an additional +24 armor against Charr.', 'Ward Spell. (14...20 seconds.) Allies in this ward have +24 armor and +24 more armor against Charr. Spirits are unaffected.', 'Ebon Battle Standard of Courage', 'Ward Spell. You plant an Ebon Battle Standard of Courage at your current location. For 14...20 seconds, non-spirit allies in this area gain +24 armor and an additional +24 armor against Charr.', 'Ward Spell. (14...20 seconds.) Allies in this ward have +24 armor and +24 more armor against Charr. Spirits are unaffected.'),
  (2232, 'Ebon Battle Standard of Wisdom', 'Ward Spell. You plant an Ebon Battle Standard of Wisdom at your current location. For 14...20 seconds, non-spirit allies in this area have a 44...60% chance to halve the recharge time of spells they cast.', 'Ward Spell. (14...20 seconds.) Spells that allies in this ward cast have a 44...60% chance to recharge 50% faster. Spirits are unaffected.', 'Ebon Battle Standard of Wisdom', 'Ward Spell. You plant an Ebon Battle Standard of Wisdom at your current location. For 14...20 seconds, non-spirit allies in this area have a 44...60% chance to halve the recharge time of spells they cast.', 'Ward Spell. (14...20 seconds.) Spells that allies in this ward cast have a 44...60% chance to recharge 50% faster. Spirits are unaffected.'),
  (2233, 'Ebon Battle Standard of Honor', 'Ward Spell. You plant an Ebon Battle Standard of Honor at your current location. For 14...20 seconds, non-spirit allies in this area strike for +8...15 damage and an additional +7...10 against Charr.', 'Ward Spell. (14...20 seconds.) Allies in this ward deal +8...15 damage and +7...10 more damage against Charr. Spirits are unaffected.', 'Ebon Battle Standard of Honor', 'Ward Spell. You plant an Ebon Battle Standard of Honor at your current location. For 14...20 seconds, non-spirit allies in this area strike for +8...15 damage and an additional +7...10 against Charr.', 'Ward Spell. (14...20 seconds.) Allies in this ward deal +8...15 damage and +7...10 more damage against Charr. Spirits are unaffected.'),
  (2234, 'Ebon Vanguard Sniper Support', 'Spell. Target foe is struck for 54...90 piercing damage and begins Bleeding for 5...25 seconds. This attack has a 10% chance of doing an additional 540...900 piercing damage. If this attack hits a Charr it has a 25% chance of doing an additional 540...900 piercing damage.', 'Spell. Deals 54...90 piercing damage and inflicts Bleeding condition (5...25 seconds). 10% chance of +540...900 piercing damage. 25% chance of +540...900 piercing damage if target foe is a Charr.', 'Ebon Vanguard Sniper Support', 'Spell. Target foe is struck for 54...90 piercing damage and begins Bleeding for 5...25 seconds. This attack has a 10% chance of doing an additional 540...900 piercing damage. If this attack hits a Charr it has a 25% chance of doing an additional 540...900 piercing damage.', 'Spell. Deals 54...90 piercing damage and inflicts Bleeding condition (5...25 seconds). 10% chance of +540...900 piercing damage. 25% chance of +540...900 piercing damage if target foe is a Charr.'),
  (2235, 'Ebon Vanguard Assassin Support', 'Spell. Summon a level 14...20 Ebon Vanguard Assassin that has Iron Palm, Fox Fangs, and Nine Tail Strike. This summoned Assassin Shadow Steps to target foe. If target foe is a Charr, the Assassin lives for 24...30 seconds. If target foe is not a Charr, the Assassin lives for 12...15 seconds.', 'Spell. Summons a level 14...20 assassin that has Iron Palm, Fox Fangs, and Nine Tail Strike; it Shadow Steps to this foe. If this foe is a Charr, the assassin lives for 24...30 seconds. If this foe is not a Charr, the assassin lives for 12...15 seconds.', 'Ebon Vanguard Assassin Support', 'Spell. Summon a level 14...20 Ebon Vanguard Assassin that has Iron Palm, Fox Fangs, and Nine Tail Strike. This summoned Assassin Shadow Steps to target foe. If target foe is a Charr, the Assassin lives for 24...30 seconds. If target foe is not a Charr, the Assassin lives for 12...15 seconds.', 'Spell. Summons a level 14...20 assassin that has Iron Palm, Fox Fangs, and Nine Tail Strike; it Shadow Steps to this foe. If this foe is a Charr, the assassin lives for 24...30 seconds. If this foe is not a Charr, the assassin lives for 12...15 seconds.'),
  (2236, 'Well of Ruin', 'Well Spell. Exploit nearest corpse or sacrifice 66% health to create a Well of Ruin at its location. For 5...30 seconds, whenever a foe in the well takes physical damage, that foe has Cracked Armor for 5...20 seconds.', 'Well Spell. (5...30 seconds.) Inflicts Cracked Armor condition (5...20 seconds) to any foe in the well that takes physical damage. Exploits a fresh corpse or sacrifices 66% health.', 'Well of Ruin', 'Well Spell. Exploit nearest corpse or sacrifice 66% health to create a Well of Ruin at its location. For 5...30 seconds, whenever a foe in the well takes physical damage, that foe has Cracked Armor for 5...20 seconds.', 'Well Spell. (5...30 seconds.) Inflicts Cracked Armor condition (5...20 seconds) to any foe in the well that takes physical damage. Exploits a fresh corpse or sacrifices 66% health.'),
  (2237, 'Atrophy', 'Hex Spell. For 3...7 seconds, target foe''s primary attribute is reduced to 0.', 'Hex Spell. (3...7 seconds.) Reduces this foe''s primary attribute to 0.', 'Atrophy', 'Hex Spell. For 3...7 seconds, target foe''s primary attribute is reduced to 0.', 'Hex Spell. (3...7 seconds.) Reduces this foe''s primary attribute to 0.'),
  (2238, 'Spear of Redemption', 'Spear Attack. If this attack hits, you deal +5...20 damage. If it fails to hit, you lose one condition.', 'Spear Attack. Deals +5...20 damage. If it fails to hit, you lose one condition.', 'Spear of Redemption', 'Spear Attack. If this attack hits, you deal +5...20 damage. If it fails to hit, you lose one condition.', 'Spear Attack. Deals +5...20 damage. If it fails to hit, you lose one condition.'),
