  (2358, '"You Move Like a Dwarf!"', 'Shout. Target foe is knocked down and takes 44...80 damage. That foe is also Crippled for 8...15 seconds.', 'Shout. Deals 44...80 damage, causes knockdown, and inflicts Crippled condition (8...15 seconds).', '"You Move Like a Dwarf!"', 'Shout. Target foe is knocked down and takes 44...80 damage. That foe is also Crippled for 8...15 seconds.', 'Shout. Deals 44...80 damage, causes knockdown, and inflicts Crippled condition (8...15 seconds).'),
  (2359, '"You Are All Weaklings!"', 'Shout. Target foe and foes adjacent to target are Weakened for 8...12 seconds.', 'Shout. Inflicts Weakness condition (8...12 seconds). Also affects adjacent foes.', '"You Are All Weaklings!"', 'Shout. Target foe and foes adjacent to target are Weakened for 8...12 seconds.', 'Shout. Inflicts Weakness condition (8...12 seconds). Also affects adjacent foes.'),
  (2360, 'Feel No Pain', 'Skill. For 30 seconds you have +2...3 Health regeneration. If you are drunk when activating this skill, you also have +200...300 maximum Health.', 'Skill. (30 seconds.) You have +2...3 Health regeneration. You have +200...300 maximum Health if you are drunk when activating this skill.', 'Feel No Pain', 'Skill. For 30 seconds you have +2...3 Health regeneration. If you are drunk when activating this skill, you also have +200...300 maximum Health.', 'Skill. (30 seconds.) You have +2...3 Health regeneration. You have +200...300 maximum Health if you are drunk when activating this skill.'),
  (2361, 'Club of a Thousand Bears', 'Melee Attack. If this attack hits, it deals +6...9 damage for each adjacent foe (maximum 60 damage). If target foe is non-human it is knocked down.', 'Melee Attack. Deals +6...9 damage for each adjacent foe (maximum 60 damage). Causes knock-down if target foe is non-human.', 'Club of a Thousand Bears', 'Melee Attack. If this attack hits, it deals +6...9 damage for each adjacent foe (maximum 60 damage). If target foe is non-human it is knocked down.', 'Melee Attack. Deals +6...9 damage for each adjacent foe (maximum 60 damage). Causes knock-down if target foe is non-human.'),
  (2374, 'Ursan Blessing', 'Elite Form. You lose all effects and take on the aspect of the bear. For 60 seconds, you have 100 armor and 750...800 Health. All your attributes are set to 0 and bear attacks replace your skills.', 'Elite Form. You lose all effects and take on the aspect of the bear (60 seconds). All your attributes are set to 0 and bear attacks replace your skills, and you have 100 armor and 750...800 Health.', 'Ursan Blessing', 'Elite Form. You lose all effects and take on the aspect of the bear. For 60 seconds, you have 100 armor and 750...800 Health. All your attributes are set to 0 and bear attacks replace your skills.', 'Elite Form. You lose all effects and take on the aspect of the bear (60 seconds). All your attributes are set to 0 and bear attacks replace your skills, and you have 100 armor and 750...800 Health.'),
  (2379, 'Volfen Blessing', 'Elite Form. You lose all effects and take on the aspect of the wolf. For 60 seconds, you have 80 armor, 660...700 Health, and 2...4 Health regeneration. All your attributes are set to 0 and wolf attacks replace your skills.', 'Elite Form. You lose all effects and take on the aspect of the wolf (60 seconds). All your attributes are set to 0 and wolf attacks replace your skills, and you have 80 armor, 660...700 Health, and 2...4 Health regeneration.', 'Volfen Blessing', 'Elite Form. You lose all effects and take on the aspect of the wolf. For 60 seconds, you have 80 armor, 660...700 Health, and 2...4 Health regeneration. All your attributes are set to 0 and wolf attacks replace your skills.', 'Elite Form. You lose all effects and take on the aspect of the wolf (60 seconds). All your attributes are set to 0 and wolf attacks replace your skills, and you have 80 armor, 660...700 Health, and 2...4 Health regeneration.'),
  (2384, 'Raven Blessing', 'Elite Form. You lose all effects and take on the aspect of the raven. For 60 seconds, you have 80 armor, 660...700 Health, and a 20...30% chance to block. All your attributes are set to 0 and raven attacks replace your skills.', 'Elite Form. You lose all effects and take on the aspect of the raven (60 seconds). All your attributes are set to 0 and raven attacks replace your skills, and you have 80 armor, 660...700 Health, and a 20...30% block chance.', 'Raven Blessing', 'Elite Form. You lose all effects and take on the aspect of the raven. For 60 seconds, you have 80 armor, 660...700 Health, and a 20...30% chance to block. All your attributes are set to 0 and raven attacks replace your skills.', 'Elite Form. You lose all effects and take on the aspect of the raven (60 seconds). All your attributes are set to 0 and raven attacks replace your skills, and you have 80 armor, 660...700 Health, and a 20...30% block chance.'),
  (2411, 'Mindbender', 'Enchantment Spell. For 10...16 seconds, you move 20...33% faster and your spells take 20% less time to cast.', 'Enchantment Spell. (10...16 seconds.) You move 20...33% faster and cast spells 20% faster.', 'Mindbender', 'Enchantment Spell. For 10...16 seconds, you move 20...33% faster and your spells take 20% less time to cast.', 'Enchantment Spell. (10...16 seconds.) You move 20...33% faster and cast spells 20% faster.'),
  (2412, 'Smooth Criminal', 'Spell. For 10...20 seconds, one random spell is disabled for target foe and Smooth Criminal is replaced by that spell. You gain 5...10 Energy.', 'Spell. (10...20 seconds.) Disables one spell. This skill becomes that spell. You gain 5...10 Energy.', 'Smooth Criminal', 'Spell. For 10...20 seconds, one random spell is disabled for target foe and Smooth Criminal is replaced by that spell. You gain 5...10 Energy.', 'Spell. (10...20 seconds.) Disables one spell. This skill becomes that spell. You gain 5...10 Energy.'),
  (2413, 'Technobabble', 'Spell. Target foe and all adjacent foes are struck for 30...40 damage. If target foe is not a boss, that foe and all adjacent foes are Dazed for 3...5 seconds.', 'Spell. Deals 30...40 damage to target and adjacent foes. Inflicts Dazed condition (3...5 seconds) on these foes if target was not a boss.', 'Technobabble', 'Spell. Target foe and all adjacent foes are struck for 30...40 damage. If target foe is not a boss, that foe and all adjacent foes are Dazed for 3...5 seconds.', 'Spell. Deals 30...40 damage to target and adjacent foes. Inflicts Dazed condition (3...5 seconds) on these foes if target was not a boss.'),
  (2414, 'Radiation Field', 'Ward Spell. For 5 seconds, foes in the area have -4...6 Health degeneration. When the portal ends, foes in the area are Diseased for 12...20 seconds.', 'Ward Spell. (5 seconds.) Causes -4...6 Health degeneration to foes in the area. End effect: inflicts Disease condition (12...20 seconds) to foes in the area.', 'Radiation Field', 'Ward Spell. For 5 seconds, foes in the area have -4...6 Health degeneration. When the portal ends, foes in the area are Diseased for 12...20 seconds.', 'Ward Spell. (5 seconds.) Causes -4...6 Health degeneration to foes in the area. End effect: inflicts Disease condition (12...20 seconds) to foes in the area.'),
  (2415, 'Asuran Scan', 'Hex Spell. For 9...12 seconds, your attacks cannot miss target foe. Killing a foe hexed with Asuran Scan removes 5% Death Penalty.', 'Hex Spell. (9...12 seconds.) You cannot miss target foe. If you kill this foe, you lose 5% Death Penalty.', 'Asuran Scan', 'Hex Spell. For 9...12 seconds, your attacks cannot miss target foe. Killing a foe hexed with Asuran Scan removes 5% Death Penalty.', 'Hex Spell. (9...12 seconds.) You cannot miss target foe. If you kill this foe, you lose 5% Death Penalty.'),
  (2416, 'Air of Superiority', 'Skill. For 20...30 seconds, you gain a random Asura benefit every time you earn experience from killing an enemy.', 'Skill. (20...30 seconds.) Gain a random Asura benefit every time you earn experience from killing an enemy.', 'Air of Superiority', 'Skill. For 20...30 seconds, you gain a random Asura benefit every time you earn experience from killing an enemy.', 'Skill. (20...30 seconds.) Gain a random Asura benefit every time you earn experience from killing an enemy.'),
  (2417, 'Mental Block', 'Enchantment Spell. For 5...11 seconds you have a 50% chance to block attacks. This enchantment is reapplied every time an enemy strikes you.', 'Enchantment Spell. (5...11 seconds.) You have 50% chance to block. Renewal: every time an enemy hits you.', 'Mental Block', 'Enchantment Spell. For 5...11 seconds you have a 50% chance to block attacks. This enchantment is reapplied every time an enemy strikes you.', 'Enchantment Spell. (5...11 seconds.) You have 50% chance to block. Renewal: every time an enemy hits you.'),
  (2418, 'Pain Inverter', 'Hex Spell. For 6...10 seconds, every time target foe deals damage that foe takes 100...140% of the damage it causes (maximum 80 damage).', 'Hex Spell. (6...10 seconds.) Deals 100...140% of the damage (maximum 80) back to target foe each time it does damage.', 'Pain Inverter', 'Hex Spell. For 6...10 seconds, every time target foe deals damage that foe takes 100...140% of the damage it causes (maximum 80 damage).', 'Hex Spell. (6...10 seconds.) Deals 100...140% of the damage (maximum 80) back to target foe each time it does damage.'),
  (2420, 'Ebon Escape', 'Spell. Shadow Step to target other ally. You and that ally are healed for 70...110 Health.', 'Spell. Heals you and target ally for 70...110. Initial effect: Shadow Step to this ally. Cannot self-target.', 'Ebon Escape', 'Spell. Shadow Step to target other ally. You and that ally are healed for 70...110 Health.', 'Spell. Heals you and target ally for 70...110. Initial effect: Shadow Step to this ally. Cannot self-target.'),
  (2421, 'Weakness Trap', 'Trap. When Weakness Trap is triggered, all nearby foes are Weakened for 10...20 seconds and take 24...50 lightning damage. All Charr are knocked down. Weakness Trap ends after 90 seconds. While activating this skill, you are easily interrupted.', 'Trap. (90 seconds.) Affects nearby foes. Deals 24...50 lightning damage. Inflicts Weakness condition (10...20 seconds). Knocks-down Charr. Easily interrupted.', 'Weakness Trap', 'Trap. When Weakness Trap is triggered, all nearby foes are Weakened for 10...20 seconds and take 24...50 lightning damage. All Charr are knocked down. Weakness Trap ends after 90 seconds. While activating this skill, you are easily interrupted.', 'Trap. (90 seconds.) Affects nearby foes. Deals 24...50 lightning damage. Inflicts Weakness condition (10...20 seconds). Knocks-down Charr. Easily interrupted.'),
  (2422, 'Winds', 'Ebon Vanguard Ritual. Create a level 4...10 spirit. All foes within its range have a 15% chance to miss with ranged attacks. This spirit dies after 54...90 seconds.', 'Ebon Vanguard Ritual. Creates a level 4...10 spirit (54...90 second lifespan.) Affects foes within range. 15% chance to miss with ranged attacks.', 'Winds', 'Ebon Vanguard Ritual. Create a level 4...10 spirit. All foes within its range have a 15% chance to miss with ranged attacks. This spirit dies after 54...90 seconds.', 'Ebon Vanguard Ritual. Creates a level 4...10 spirit (54...90 second lifespan.) Affects foes within range. 15% chance to miss with ranged attacks.'),
  (2423, 'Dwarven Stability', 'Enchantment Spell. For 24...30 seconds, your stances last 55...100% longer. If you activated this skill while drunk, you cannot be knocked down.', 'Enchantment Spell. (24...30 seconds.) Your stances last 55...100% longer. You cannot be knocked-down if you activated this skill while drunk .', 'Dwarven Stability', 'Enchantment Spell. For 24...30 seconds, your stances last 55...100% longer. If you activated this skill while drunk, you cannot be knocked down.', 'Enchantment Spell. (24...30 seconds.) Your stances last 55...100% longer. You cannot be knocked-down if you activated this skill while drunk .'),
  (3422, 'Time Ward', 'Elite Ward Spell. You create a Time Ward at your current location. For 6...20 seconds, non-spirit allies in this area cast spells 15...20% faster and recharge skills 15...20% faster. PvE Skill', 'Elite Ward Spell. (6...20 seconds.) Allies in this ward cast spells 15...20% faster and recharge skills 15...20% faster. Allied spirits are not affected. PvE Skill', 'Time Ward', 'Elite Ward Spell. You create a Time Ward at your current location. For 6...20 seconds, non-spirit allies in this area cast spells 15...20% faster and recharge skills 15...20% faster. PvE Skill', 'Elite Ward Spell. (6...20 seconds.) Allies in this ward cast spells 15...20% faster and recharge skills 15...20% faster. Allied spirits are not affected. PvE Skill'),
